/* Login / role permissions — Release 276 Firebase Authentication.
   Authentication and role claims are verified by Firebase before app.js is loaded.
   No operational/admin password or password hash is stored in browser code. */
let userRole = "operator";

function closeLogin() {
  const overlay = document.getElementById("loginOverlay");
  if (overlay) overlay.style.display = "none";
}

function isAdminRestrictedElement(el) {
  if (!el) return false;
  // DEV463 PIN CONTROL BEGIN
  if ((el.closest && el.closest('#airfieldInfoEditor')) || (el.matches && el.matches('[data-airfield-edit]'))) return !window.FISO_INFO_PIN?.canEdit?.();
  // DEV463 PIN CONTROL END
  // MAP TIME changes only this display; it never writes operational data.
  if (el.id === "fisoTimeApply" && el.closest && el.closest("#fisoTimePanel")) return false;
  if (el.closest && el.closest(".admin-access")) return false;
  const label = (el.textContent || el.value || "").trim();
  const id = String(el.id || "");
  const adminIdMatch = /(hazAdd|hazImport|hazExport|airfieldFile|airfieldExport|airfieldClear|paraDownloadFile|paraDownloadExport|dangerDownloadFile|dangerDownloadExport|enr51File|enr51Preview|enr51Install|enr51Export|enr51Clear|enr51InsertAreaSearch|enr51InsertAreaBtn|pibFile|clearPlottedNotamsBtn|hazdam|paraSite|chartTif|chartSetup|applyTraffic|hlAdd)/i.test(id);
  const adminLabelMatch = /\b(Add|Save|Delete|Edit|Import|Export|Upload|Clear all|Load Chart|Apply)\b/i.test(label);
  return adminIdMatch || adminLabelMatch;
}

function viewerEditAllowedElement(el) {
  if (!el) return false;
  if (el.matches && el.matches('.tab-btn[data-tab="airfield-met"]')) return true;
  if (el.closest && el.closest("#tab-airfield-met")) return true;
  if (el.closest && el.closest("#aaraManualModal")) return true;
  if (el.matches && el.matches("[data-aara-manual],[data-aara-save],[data-aara-clear],[data-aara-cancel]")) return true;
  return false;
}

function forceViewOnlyMapWidth() {
  if(userRole!=="viewer") return;
  var main=document.querySelector("main");
  var mapEl=document.getElementById("map");
  var strips=document.getElementById("stripsPanel");
  var side=document.getElementById("side");
  if(!main||!mapEl)return;

  // INFO is closed in View Only at startup, but an operator must still be able
  // to open it on mobile. Do not let the resize guard immediately close it again.
  if(side && !side.classList.contains("open")){
    side.style.flexBasis="0px";
    side.style.width="0px";
    side.style.minWidth="0px";
    side.style.maxWidth="0px";
    side.style.overflow="hidden";
  } else if(side) {
    side.style.removeProperty("flex-basis");
    side.style.removeProperty("width");
    side.style.removeProperty("min-width");
    side.style.removeProperty("max-width");
    side.style.removeProperty("overflow");
  }

  // Let flexbox own the actual map width. Do not leave an old pixel width
  // behind from a previous Operator/Admin layout.
  mapEl.style.removeProperty("width");
  mapEl.style.flex="1 1 0px";
  mapEl.style.flexBasis="0px";
  mapEl.style.minWidth="0px";
  mapEl.style.maxWidth="none";

  // Leaflet keeps an internal cached viewport size. If INFO was 500px wide
  // when the map initialised, closing INFO changes the DOM width but not that
  // cached viewport until invalidateSize runs.
  try{
    if(typeof map!=="undefined" && map && map.invalidateSize){
      map.invalidateSize({pan:false,animate:false});
    }
  }catch(_e){}
}

function installViewOnlyMapResizeGuard(){
  var mapEl=document.getElementById("map");
  if(!mapEl || mapEl.dataset.ffViewResizeGuard==="1")return;
  mapEl.dataset.ffViewResizeGuard="1";

  var refresh=function(){
    if(userRole!=="viewer")return;
    forceViewOnlyMapWidth();
  };

  // Watch the actual container dimension so Safari/local file testing and
  // delayed panel CSS changes cannot leave the tile layer at the old width.
  if(typeof ResizeObserver==="function"){
    try{
      var ro=new ResizeObserver(function(){refresh();});
      ro.observe(mapEl);
      window.__ffappViewOnlyMapResizeObserver=ro;
    }catch(_e){}
  }

  window.addEventListener("resize",function(){setTimeout(refresh,30);});
  window.addEventListener("ffapp-view-only-opened",function(){
    [0,80,220,500,1000,1800,3000,4500].forEach(function(ms){
      setTimeout(refresh,ms);
    });
  });

  // Also cover the initial app boot sequence, where app.js/map creation can
  // finish after the authenticated/view-only role was already selected.
  [0,120,350,800,1500,2500,4000].forEach(function(ms){
    setTimeout(refresh,ms);
  });
}


function applyViewOnlyLayout() {
  if (!(userRole === "viewer" || userRole === "vieweredit")) return;
  var main=document.querySelector("main");
  var strips=document.getElementById("stripsPanel");
  var side=document.getElementById("side");
  if(main){
    // DEV470: keep the startup/user-selected STRIPS state for every role.
    main.classList.add("info-collapsed");
  }
  if(strips) strips.classList.remove("mob-strips");
  if(side){
    // Release319: role application never opens INFO automatically.
    side.classList.remove("open");
  }
  // Leaflet can initialise before or after INFO collapses. Keep its cached
  // viewport synchronized until the View Only layout has fully settled.
  if(userRole==="viewer") installViewOnlyMapResizeGuard();
  [0,80,220,500,1000,1800,3000,4500].forEach(function(delay){
    setTimeout(function(){
      try {
        if(userRole==="viewer") forceViewOnlyMapWidth();
        else if(typeof map!=="undefined" && map && map.invalidateSize) map.invalidateSize({pan:false,animate:false});
      } catch(_e){}
    },delay);
  });
}

function forceInfoClosedOnStartup() {
  var main=document.querySelector("main");
  var side=document.getElementById("side");
  if(main) main.classList.add("info-collapsed");
  if(side) side.classList.remove("open");
  try {
    if(typeof map!=="undefined" && map && map.invalidateSize) {
      [0,100,350].forEach(function(ms){setTimeout(function(){try{map.invalidateSize(true);}catch(_e){}},ms);});
    }
  } catch(_e) {}
}

function ffappWhenDomReady(fn) {
  if (typeof fn !== "function") return;
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", fn, { once: true });
  } else {
    // app.js is injected after authentication, so DOMContentLoaded may already
    // have fired on a cold start. Run on the next microtask instead of waiting
    // for an event that will never fire.
    Promise.resolve().then(fn);
  }
}

ffappWhenDomReady(function(){
  forceInfoClosedOnStartup();
});

function isViewerWriteElement(el) {
  if (!el) return false;
  // DEV451 final permission gate: these operational map panels stay inactive
  // in VIEW APP even though ordinary Leaflet navigation is allowed.
  if (["fisoLayersToggle", "fisoParasToggle", "fisoTimeToggle"].includes(el.id)) return true;
  if (el.closest && el.closest("#fisoLayersPanel,#fisoParasPanel,#fisoTimePanel")) return true;
  // Aircraft visibility is a local display preference, not an operational edit.
  if (el.id === "toggleAircraft") return false;
  if (el.id === "searchInput" || el.id === "searchBtn" || el.id === "searchClearBtn") return false;
  if (el.id === "dev454StripsClose" || el.id === "dev454InfoClose") return false; // Local panel dismissal only.
  if (el.id === "infoCollapseHandle" || el.id === "stripsCollapseHandle" || el.id === "ffauthHeaderLogoutBtn" || el.id === "ffauthSwitchUserBtn") return false;
  if (el.closest && el.closest(".leaflet-control")) return false;
  if (el.closest && el.closest("#adminAccessPopover")) return true;
  if (el.closest && el.closest("#stripsPanel") && el.matches && el.matches("input,textarea,select,button,[contenteditable='true']")) return true;
  if (el.matches && el.matches("input[type='file'],input[type='checkbox'],input[type='radio'],input[type='number'],input[type='date'],input[type='time'],input[type='datetime-local'],textarea,[contenteditable='true']")) return true;
  if (isAdminRestrictedElement(el)) return true;
  const id = String(el.id || "");
  const action = String((el.dataset && (el.dataset.action || el.dataset.act || el.dataset.afAct || el.dataset.a)) || "");
  const label = String(el.textContent || el.value || "").trim();
  if (/(edit|save|delete|remove|add|create|upload|import|export|install|clearall|clearPlotted|initiate|plot|apply|reset|route)/i.test(id + " " + action)) return true;
  if (/\b(Edit|Save|Delete|Remove|Add|Create|Upload|Import|Export|Install|Clear all|Initiate|Plot|Apply|Reset|Route)\b/i.test(label)) return true;
  return false;
}

function applyViewerReadOnlyGuards(root) {
  if (userRole !== "viewer") return;
  root = root || document;
  const selector = "button,input,textarea,select,[contenteditable='true']";
  function lock(el){
    if (!isViewerWriteElement(el)) return;
    if (el.dataset.ffViewerReadOnly !== "1") {
      el.dataset.ffViewerReadOnly = "1";
      el.dataset.ffViewerWasDisabled = el.disabled ? "1" : "0";
    }
    if ("disabled" in el) el.disabled = true;
    if (el.hasAttribute && el.hasAttribute("contenteditable")) el.setAttribute("contenteditable","false");
    el.setAttribute && el.setAttribute("aria-disabled","true");
  }
  if (root.matches && root.matches(selector)) lock(root);
  if (root.querySelectorAll) root.querySelectorAll(selector).forEach(lock);
}

function installViewerReadOnlyGuard() {
  if (window.__ffappViewerGuardInstalled) return;
  window.__ffappViewerGuardInstalled = true;
  function blockIfWrite(e) {
    if (userRole !== "viewer") return;
    var el=e.target && e.target.closest ? e.target.closest("button,input,textarea,select,[contenteditable],a") : e.target;
    if (!isViewerWriteElement(el)) return;
    e.preventDefault(); e.stopPropagation();
  }
  document.addEventListener("click", blockIfWrite, true);
  document.addEventListener("change", blockIfWrite, true);
  document.addEventListener("submit", blockIfWrite, true);
  if (typeof MutationObserver === "function") {
    // DEV451: examine added subtrees, not every control after unrelated clock/map updates.
    // The synchronous capture guard above remains authoritative before handlers run.
    var mo=new MutationObserver(function(mutations){
      if(userRole!=="viewer") return;
      const roots=new Set();
      mutations.forEach(function(m){
        m.addedNodes.forEach(function(n){ if(n.nodeType===1) roots.add(n); });
        // Text changes inside an existing button can change its restriction label.
        var control=m.target.closest && m.target.closest("button,input,textarea,select,[contenteditable]");
        if(control) roots.add(control);
      });
      roots.forEach(function(root){ applyViewerReadOnlyGuards(root); });
    });
    mo.observe(document.documentElement,{childList:true,subtree:true});
    window.__ffappViewerMutationObserver=mo;
  }
}

function applyPermissions() {
  // DEV341: Viewer is the normal application in read-only mode. There is no
  // separate View Only layout, map path, INFO path or operational data source.
  forceInfoClosedOnStartup();
  const isAdmin = userRole === "admin";
  const isViewer = userRole === "viewer";
  document.body.classList.toggle("admin-mode", isAdmin);
  document.body.classList.toggle("operator-mode", !isAdmin && !isViewer);
  document.body.classList.toggle("view-only-mode", isViewer);
  document.body.classList.remove("view-edit-mode");

  // Restore controls that an earlier Viewer session may have locked, then apply
  // the current role's restrictions. Viewer keeps normal navigation/search/map.
  document.querySelectorAll("[data-ff-viewer-read-only='1']").forEach(function(el){
    if (!isViewer) {
      if (el.dataset.ffViewerWasDisabled !== "1" && "disabled" in el) el.disabled=false;
      el.removeAttribute("aria-disabled");
      delete el.dataset.ffViewerReadOnly; delete el.dataset.ffViewerWasDisabled;
    }
  });

  document.querySelectorAll("button,input,textarea,select").forEach(function(el){
    if (!isAdminRestrictedElement(el)) return;
    if (isAdmin) {
      if (el.dataset.adminLocked === "true") { el.disabled=false; el.style.opacity=""; delete el.dataset.adminLocked; }
    } else {
      el.disabled=true; el.style.opacity="0.5"; el.dataset.adminLocked="true";
    }
  });

  // All INFO tabs remain visible in Viewer mode. Only controls that can alter
  // operational state are disabled; viewing, searching, tab navigation, map
  // interaction and popup inspection remain identical to Operator/Admin.
  document.querySelectorAll("#side .tab-btn").forEach(function(btn){ btn.style.display=""; });
  // DEV343: PARA SITES and DANGER AREAS remain available to Admin, but are
  // hidden from Viewer/Operator navigation. Their underlying map data remains
  // available to all roles as required by the operational display.
  document.querySelectorAll("#notamWorkspaceSubnav [data-admin-notam-sub='1']").forEach(function(btn){
    btn.style.display=isAdmin ? "" : "none";
  });
  if(!isAdmin){
    var activeSub=document.querySelector("#notamWorkspaceSubnav .btn.primary[data-admin-notam-sub='1']");
    if(activeSub && typeof showNotamSubpanel==="function") showNotamSubpanel("notam");
  }
  installViewerReadOnlyGuard();
  if (isViewer) {
    ["fisoLayersPanel", "fisoParasPanel", "fisoTimePanel"].forEach(function(id){
      var panel=document.getElementById(id); if(panel) panel.hidden=true;
    });
    ["fisoLayersToggle", "fisoParasToggle", "fisoTimeToggle"].forEach(function(id){
      var button=document.getElementById(id); if(button) button.setAttribute("aria-expanded","false");
    });
    applyViewerReadOnlyGuards();
  }

  try { if(typeof renderAaraAreas==="function") renderAaraAreas(); } catch(_e) {}
  const toggle=document.getElementById("adminAccessToggle");
  if (toggle && !toggle.dataset.authManaged) {
    toggle.textContent=isAdmin ? "ADMIN" : (isViewer ? "VIEWER" : "OPERATOR");
    toggle.classList.toggle("admin-on",isAdmin);
  }
  try { if(typeof map!=="undefined" && map && map.invalidateSize) setTimeout(function(){map.invalidateSize({pan:false,animate:false});},30); } catch(_e) {}
}

function setAdminPopover(open) {
  const pop = document.getElementById("adminAccessPopover");
  const toggle = document.getElementById("adminAccessToggle");
  if (!pop) return;
  pop.hidden = !open;
  if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
}

