window.setFFAppAuthenticatedRole = function(role){
  var r=String(role || "").toLowerCase();
  userRole = r==="admin" ? "admin" : (r==="viewer"||r==="viewonly"||r==="vieweredit" ? "viewer" : "operator");
  forceInfoClosedOnStartup();
  applyPermissions();
  // Release326: app.js can subscribe to Firebase before ffapp-auth has applied
  // the final role. Reconcile AUTO PIB once that role is known so VIEW ONLY does
  // not miss a snapshot that arrived during startup.
  try {
    if (typeof sharedAutoPibLoaded !== "undefined" && sharedAutoPibLoaded && typeof applySharedAutoPibHazards === "function") {
      setTimeout(function(){ try { applySharedAutoPibHazards("authenticated role applied"); } catch(_e) {} }, 0);
    }
  } catch(_e) {}
};
