    var remaining=window.ffappIsTestTime()?Math.max(0,Math.ceil((state.realBaseMs+30000-Date.now())/1000)):0;
    if(window.ffappIsTestTime()&&!remaining){window.ffappResetOperationalTime();return;}
    var countdown=document.getElementById("fisoMapTimeReturnCountdown");
    if(countdown)countdown.textContent=window.ffappIsTestTime()?"NOT LIVE — returning to LIVE in "+remaining+"s":"";
    var mapTimeWarning=document.getElementById("fisoMapTimeWarning"),selectedTime=document.getElementById("fisoMapTimeSelectedUTC");
    if(mapTimeWarning)mapTimeWarning.hidden=!window.ffappIsTestTime();
