    var c=document.getElementById("clock"),cd=document.getElementById("clockDate"),panel=document.getElementById("utcClockPanel"),status=document.getElementById("clockTestStatus");
    if(c)c.textContent=pad(d.getUTCHours())+":"+pad(d.getUTCMinutes())+":"+pad(d.getUTCSeconds());
    if(cd)cd.textContent=pad(d.getUTCDate())+" "+months[d.getUTCMonth()]+" "+d.getUTCFullYear();
