  function utcHazardResetDateKey() {
    return new Date().toISOString().slice(0, 10);
  }

  function resetHazardPinsIfUtcDayChanged() {
    var todayKey = utcHazardResetDateKey();
    var lastKey = null;
    try {
      lastKey = localStorage.getItem(LS_KEY_HAZARD_PIN_RESET_DATE);
    } catch (e) {}

    // First run after upgrade: start tracking today's UTC date, but do not
    // unexpectedly remove hazards that are already on the operator's map.
    if (!lastKey) {
      try { localStorage.setItem(LS_KEY_HAZARD_PIN_RESET_DATE, todayKey); } catch (e) {}
      return false;
    }

    if (lastKey === todayKey) return false;

    hazards = [];
    saveJSON(LS_KEY_HAZARDS, hazards);
    try { localStorage.setItem(LS_KEY_HAZARD_PIN_RESET_DATE, todayKey); } catch (e) {}

    if (typeof renderHazards === "function") renderHazards();
    if (typeof clearHazPickPreview === "function") clearHazPickPreview();
    if (typeof updateHazNextRef === "function") updateHazNextRef(true);
    if (typeof syncAutoPibHazards === "function") {
      setTimeout(function () { autoPibMarkReady("UTC day reset"); }, 100);
    }
    console.info("FFApp: plotted hazard pins reset at 0000Z; next pin will start from Pin #1.");
    return true;
  }

