  var FFAPP_BUILTIN_PROTECTED_SQUAWKS = ["1177", "0027", "0030", "0037", "7400", "7500", "7600", "7700"];
  function normaliseSquawkValue(value) {
    var sq = String(value || "").replace(/\D/g, "").slice(0, 4);
    return sq.length === 4 ? sq : "";
  }
  function getProtectedSquawks() {
    var out = [];
    function add(value) {
      var sq = normaliseSquawkValue(value);
      if (sq && out.indexOf(sq) === -1) out.push(sq);
    }
    FFAPP_BUILTIN_PROTECTED_SQUAWKS.forEach(add);
    (settings.customSqkList || []).forEach(add);
    return out;
  }
  window.FFAPP_PROTECTED_SQUAWKS = {
    builtIn: FFAPP_BUILTIN_PROTECTED_SQUAWKS.slice(),
    get: getProtectedSquawks,
    isProtected: function (value) {
      var sq = normaliseSquawkValue(value);
      return !!sq && getProtectedSquawks().indexOf(sq) !== -1;
    },
  };

