  // Release119: guarantee every plotted hazard has a stable identity, including
  // legacy/imported hazards created before internal IDs were introduced.
  function ensureHazardIds(list) {
    var seen = {};
    var changed = false;
    (Array.isArray(list) ? list : []).forEach(function (h, idx) {
      if (!h || typeof h !== "object") return;
      var current = h.id == null ? "" : String(h.id).trim();
      if (!current || current === "undefined" || current === "null" || seen[current]) {
        current = "haz_" + Date.now().toString(36) + "_" + idx.toString(36) + "_" + Math.random().toString(36).slice(2, 8);
        h.id = current;
        changed = true;
      } else if (h.id !== current) {
        h.id = current;
        changed = true;
      }
      seen[current] = true;
    });
    return changed;
  }
  ensureHazardIds(hazards);

