  function findHazardIndexById(id) {
    var key = id == null ? "" : String(id);
    for (var i = 0; i < hazards.length; i++) {
      if (hazards[i] && String(hazards[i].id) === key) return i;
    }
    return -1;
  }

  function findHazardById(id) {
    var idx = findHazardIndexById(id);
    return idx >= 0 ? hazards[idx] : null;
  }
  resetHazardPinsIfUtcDayChanged();
