  var hazardMarkers = {}; // id -> marker, runtime only
  var hazardShapes = {}; // id -> polygon/polyline for multi-point areas, runtime only
  var hazardRadiusShapes = {}; // id -> radius circle for TDA / SAR OPS
  // Release249: GNSS/GPS/radio-frequency jamming boundaries are normally hidden.
  // They are revealed only from the jamming pin and remain visible for five
  // seconds after the associated popup closes. This is transient UI state only.
  var gnssJammingAreaState = {}; // hazard id -> { open:boolean, until:number }
  // Dev328: AERIAL FILMING polygons are normally hidden. Clicking the associated
  // hazard pin reveals a light-yellow copy of the published area; it remains for
  // five seconds after the popup is closed. This state is visual only.
  var aerialFilmingAreaState = {}; // hazard id -> { open:boolean, until:number }

  function isAerialFilmingHazard(h) {
    if (!h) return false;
    var hay = (String(h.displayLabel || "") + " " + String(h.popupTitle || "") + " " +
      String(h.notam || "") + " " + String(h.autoRule || "")).toUpperCase();
    return h.areaStyle === "MULTIPLE_HEL_OPS" || /\bAERIAL\s+FILMING\b/.test(hay) || /\bFILMING\s+FROM\s+AN\s+(?:ACFT|AIRCRAFT)\b/.test(hay);
  }

  function aerialFilmingAreaShouldShow(h) {
    if (!isAerialFilmingHazard(h)) return false;
    var st = aerialFilmingAreaState[String(h.id)];
    return !!(st && (st.open === true || Number(st.until || 0) > Date.now()));
  }

  function setAerialFilmingAreaOpen(h) {
    if (!isAerialFilmingHazard(h)) return;
    aerialFilmingAreaState[String(h.id)] = { open:true, until:0 };
  }

  function keepAerialFilmingAreaAfterPopup(h) {
    if (!isAerialFilmingHazard(h)) return;
    var id = String(h.id);
    var until = Date.now() + 5000;
    aerialFilmingAreaState[id] = { open:false, until:until };
    setTimeout(function(){
      var st = aerialFilmingAreaState[id];
      if (!st || st.open || Number(st.until || 0) > Date.now()) return;
      delete aerialFilmingAreaState[id];
      try {
        if (hazardShapes[id] && hazardLayer) hazardLayer.removeLayer(hazardShapes[id]);
      } catch(_e) {}
      delete hazardShapes[id];
    }, 5050);
  }

  function isGnssJammingHazard(h) {
    return !!(h && (h.areaStyle === "GNSS_JAMMING" ||
      h.areaStyle === "INFO_EXERCISE" ||
      /\bGNSS\b[\s\S]{0,80}\b(?:JAMMING|SPOOF(?:ING|NIG))\b/i.test(String(h.notam || "")) ||
      /\bRADIO\s+FREQUENCY\s+JAMMING\b/i.test(String(h.notam || ""))));
  }

  function gnssJammingAreaShouldShow(h) {
    if (!isGnssJammingHazard(h)) return true;
    var st = gnssJammingAreaState[String(h.id)];
    return !!(st && (st.open === true || Number(st.until || 0) > Date.now()));
  }

  function setGnssJammingAreaOpen(h) {
    if (!isGnssJammingHazard(h)) return;
    gnssJammingAreaState[String(h.id)] = { open:true, until:0 };
  }

  function keepGnssJammingAreaAfterPopup(h) {
    if (!isGnssJammingHazard(h)) return;
    var id = String(h.id);
    var until = Date.now() + 5000;
    gnssJammingAreaState[id] = { open:false, until:until };
    setTimeout(function(){
      var st = gnssJammingAreaState[id];
      if (!st || st.open || Number(st.until || 0) > Date.now()) return;
      delete gnssJammingAreaState[id];
      try {
        if (hazardShapes[id] && hazardLayer) hazardLayer.removeLayer(hazardShapes[id]);
      } catch(_e) {}
      delete hazardShapes[id];
    }, 5050);
  }
