  UK_FIR_WAYPOINTS.forEach(function (p) {
    ukWaypointByIdent[p.ident] = p;
  });
  var ukWaypointLayer = L.layerGroup();
  var ukWaypointMarkers = {};
  var ukWaypointNamesVisible = false;
  var ukWaypointSearchMarker = null;
  var rbFocusedEnd = null; // null | "start" | "end"
  var rbStartWaypointIdent = null,
    rbEndWaypointIdent = null;
  var rbStartPlaceLabel = null,
    rbEndPlaceLabel = null; // airfield/location label for typed R&B endpoints

  var pchRbLine = null; // separate auto R&B line shown only during PCH alert

  /* ============================ UTIL ============================ */
  function nmToMeters(nm) {
    return nm * 1852;
  }
  function toRad(d) {
    return (d * Math.PI) / 180;
  }
  function haversineNm(lat1, lon1, lat2, lon2) {
    var R = 3440.065; // earth radius in NM
    var dLat = toRad(lat2 - lat1),
      dLon = toRad(lon2 - lon1);
    var a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(toRad(lat1)) *
        Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  }

  // Distance from an aircraft position to the nearest edge of a multi-leg NOTAM polygon/line.
  // Uses a local tangent-plane projection in NM, accurate enough for UK NOTAM-sized areas.
  function pointToSegmentDistanceNm(px, py, ax, ay, bx, by) {
    var dx = bx - ax, dy = by - ay;
    if (dx === 0 && dy === 0) {
      var ex = px - ax, ey = py - ay;
      return Math.sqrt(ex * ex + ey * ey);
    }
    var t = ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy);
    t = Math.max(0, Math.min(1, t));
    var qx = ax + t * dx, qy = ay + t * dy;
    var rx = px - qx, ry = py - qy;
    return Math.sqrt(rx * rx + ry * ry);
  }

  function distanceToMultiHazardBoundaryNm(lat, lon, points) {
    if (!Array.isArray(points) || points.length < 2) return Infinity;
    var refLat = Number(lat) || 0;
    var cosLat = Math.cos(toRad(refLat));
    function project(p) {
      return {
        x: (Number(p.lon) - lon) * 60 * cosLat,
        y: (Number(p.lat) - lat) * 60,
      };
    }
    var pxy = { x: 0, y: 0 };
    var minNm = Infinity;
    for (var i = 0; i < points.length - 1; i++) {
      var a = project(points[i]);
      var b = project(points[i + 1]);
      minNm = Math.min(minNm, pointToSegmentDistanceNm(pxy.x, pxy.y, a.x, a.y, b.x, b.y));
    }
    // Multi-leg NOTAM polygons are closed automatically by the app.
    if (points.length >= 3) {
      var first = project(points[0]);
      var last = project(points[points.length - 1]);
      minNm = Math.min(minNm, pointToSegmentDistanceNm(pxy.x, pxy.y, last.x, last.y, first.x, first.y));
    }
    return minNm;
  }
  // Destination point given a start, an initial bearing (deg true), and a distance (nm).
  // Standard spherical "direct geodetic" formula -- used for both squawk vector lines and
  // the Range & Bearing tool's default placement.
  function destinationPoint(lat, lon, bearingDeg, distanceNm) {
    var R = 3440.065;
    var delta = distanceNm / R;
    var theta = toRad(bearingDeg);
    var phi1 = toRad(lat),
      lambda1 = toRad(lon);
    var phi2 = Math.asin(
      Math.sin(phi1) * Math.cos(delta) +
        Math.cos(phi1) * Math.sin(delta) * Math.cos(theta),
    );
    var lambda2 =
      lambda1 +
      Math.atan2(
        Math.sin(theta) * Math.sin(delta) * Math.cos(phi1),
        Math.cos(delta) - Math.sin(phi1) * Math.sin(phi2),
      );
    var lon2 = (((lambda2 * 180) / Math.PI + 540) % 360) - 180; // normalize to -180..180
    return [(phi2 * 180) / Math.PI, lon2];
  }
  // Initial bearing (deg true, 0-360) from point 1 to point 2.
  function initialBearingDeg(lat1, lon1, lat2, lon2) {
    var phi1 = toRad(lat1),
      phi2 = toRad(lat2),
      dLambda = toRad(lon2 - lon1);
    var y = Math.sin(dLambda) * Math.cos(phi2);
    var x =
      Math.cos(phi1) * Math.sin(phi2) -
      Math.sin(phi1) * Math.cos(phi2) * Math.cos(dLambda);
    return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
  }
  function pad(n) {
    return n < 10 ? "0" + n : "" + n;
  }
  function fmtNotamDate(s) {
    // expects 10-digit YYMMDDHHMM, or "PERM"/"UFN"
    if (!s) return "&ndash;";
    s = s.trim();
    if (/PERM|UFN/i.test(s)) return s.toUpperCase();
    var m = s.match(/^(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/);
    if (!m) return s;
    var yy = parseInt(m[1], 10);
    var year = yy < 70 ? 2000 + yy : 1900 + yy;
    var months = [
      "Jan",
      "Feb",
      "Mar",
      "Apr",
      "May",
      "Jun",
      "Jul",
      "Aug",
      "Sep",
      "Oct",
      "Nov",
      "Dec",
    ];
    var mon = months[parseInt(m[2], 10) - 1] || m[2];
    return m[3] + " " + mon + " " + year + " " + m[4] + ":" + m[5] + "Z";
  }
  function uid() {
    return Math.random().toString(36).slice(2, 10);
  }
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      }[c];
    });
  }

  // Render telephone numbers as click-to-call links. Handles single numbers and
  // common multi-number formats such as "01234 567890 / 07700 900123".
  function cleanTelHref(phone) {
    var s = String(phone == null ? "" : phone).trim();
    if (!s) return "";
    var hadPlus = /^\s*\+/.test(s);
    s = s.replace(/[^0-9]/g, "");
    if (!s) return "";
    return (hadPlus ? "+" : "") + s;
  }

  function telLinksHtml(phone, cls) {
    var text = String(phone == null ? "" : phone).trim();
    if (!text) return "";
    var parts = text.split(/\s*(?:\/|,|;|\bor\b|&)\s*/i).filter(function (x) {
      return String(x || "").trim() !== "";
    });
    if (!parts.length) parts = [text];
    return parts
      .map(function (part) {
        var label = String(part || "").trim();
        var href = cleanTelHref(label);
        return href
          ? '<a href="tel:' + esc(href) + '" class="' + esc(cls || "ff-phone-link") + '">' + esc(label) + '</a>'
          : esc(label);
      })
      .join(' <span class="ff-phone-sep">/</span> ');
  }

  /* ============================ MAP INIT ============================ */
  var map = L.map("map", {
    zoomControl: false,
    attributionControl: true,
    // DEV407 — prevent zooming farther out than the requested UK-wide overview.
    minZoom: 6,
  }).setView([51 + 50/60, -(1 + 50/60)], 7);

  // DEV470: every load starts with the crosshair at 51°50′N 001°50′W.
  // Home settings remain independent of the requested startup map centre.
  // The authenticated workspace is hidden while Leaflet initialises. Centre
  // once its actual viewport exists, so the crosshair is not at a corner.
  (function(){
    var initialCentreApplied=false,observer=null;
    function centreInitialViewport(){
      var el=map.getContainer();
      if(initialCentreApplied||!el.clientWidth||!el.clientHeight)return;
      initialCentreApplied=true;
      if(observer)observer.disconnect();
      map.invalidateSize({pan:false,animate:false});
      map.setView([51 + 50/60, -(1 + 50/60)],7,{animate:false,reset:true});
    }
    if(typeof ResizeObserver==='function'){
      observer=new ResizeObserver(centreInitialViewport);observer.observe(map.getContainer());
    }
    requestAnimationFrame(centreInitialViewport);
  })();
  L.control.zoom({ position: "bottomleft" }).addTo(map);


  // Dev342 — unobtrusive latitude / longitude chart graticule.
  // Labels are kept deliberately small and placed at the chart edges.
  var latLonGridLayer = L.layerGroup().addTo(map);
  function gridCoordLabel(value, isLat) {
    var abs = Math.abs(value);
    var deg = Math.floor(abs + 1e-9);
    var min = Math.round((abs - deg) * 60);
    if (min === 60) { deg += 1; min = 0; }
    var hemi = isLat ? (value >= 0 ? "N" : "S") : (value >= 0 ? "E" : "W");
    return deg + "°" + (min ? String(min).padStart(2,"0") + "′" : "") + hemi;
  }
  function redrawLatLonGrid() {
    latLonGridLayer.clearLayers();
    var b = map.getBounds();
    var z = map.getZoom();
    var step = z >= 10 ? 0.25 : (z >= 8 ? 0.5 : 1.0);
    var south = b.getSouth(), north = b.getNorth(), west = b.getWest(), east = b.getEast();
    var lineStyle = { color: "#111", weight: 0.6, opacity: 0.25, interactive: false };
    var firstLat = Math.ceil(south / step) * step;
    var firstLon = Math.ceil(west / step) * step;
    for (var lat = firstLat; lat <= north + 1e-8; lat += step) {
      var la = Math.round(lat * 1000000) / 1000000;
      var latText = gridCoordLabel(la,true);
      L.polyline([[la, west],[la, east]], lineStyle).addTo(latLonGridLayer);
      // Dev348 — show latitude on BOTH west and east chart edges.  Both labels
      // use exactly the same small font treatment as the longitude labels and
      // are anchored inward so they remain visible rather than clipping off-map.
      // Keep latitude labels a few pixels INSIDE the visible map. Markers placed
      // exactly on getBounds().west/east can be clipped by Leaflet at the pane edge.
      var yLat = map.latLngToContainerPoint([la, map.getCenter().lng]).y;
      var leftLatLng = map.containerPointToLatLng([8, yLat]);
      var rightLatLng = map.containerPointToLatLng([map.getSize().x - 8, yLat]);
      L.marker(leftLatLng, {interactive:false, zIndexOffset:5000, icon:L.divIcon({className:"fiso-grid-label-wrap",html:'<span class="fiso-grid-label fiso-grid-lat fiso-grid-lat-left">'+latText+'</span>',iconSize:[48,14],iconAnchor:[0,7]})}).addTo(latLonGridLayer);
      L.marker(rightLatLng, {interactive:false, zIndexOffset:5000, icon:L.divIcon({className:"fiso-grid-label-wrap",html:'<span class="fiso-grid-label fiso-grid-lat fiso-grid-lat-right">'+latText+'</span>',iconSize:[48,14],iconAnchor:[48,7]})}).addTo(latLonGridLayer);
    }
    for (var lon = firstLon; lon <= east + 1e-8; lon += step) {
      var lo = Math.round(lon * 1000000) / 1000000;
      L.polyline([[south, lo],[north, lo]], lineStyle).addTo(latLonGridLayer);
      // DEV422 — show longitude labels on BOTH the north and south chart edges.
      // Keep both rows well inside the visible map so the header at the north
      // and Leaflet attribution / NOTAM ticker at the south cannot obscure them.
      var xLon = map.latLngToContainerPoint([map.getCenter().lat, lo]).x;
      var topLonLatLng = map.containerPointToLatLng([xLon, 24]);
      var bottomLonLatLng = map.containerPointToLatLng([xLon, map.getSize().y - 42]);
      var lonHtml = '<span class="fiso-grid-label fiso-grid-lon">'+gridCoordLabel(lo,false)+'</span>';
      L.marker(topLonLatLng, {interactive:false, zIndexOffset:5000, icon:L.divIcon({className:"fiso-grid-label-wrap",html:lonHtml,iconSize:[42,12],iconAnchor:[21,0]})}).addTo(latLonGridLayer);
      L.marker(bottomLonLatLng, {interactive:false, zIndexOffset:5000, icon:L.divIcon({className:"fiso-grid-label-wrap",html:lonHtml,iconSize:[42,12],iconAnchor:[21,12]})}).addTo(latLonGridLayer);
    }
  }
  map.on("moveend zoomend resize", redrawLatLonGrid);
  window.requestAnimationFrame(redrawLatLonGrid);

  // Release 272 — dynamic nautical-mile scale. The bar is calculated from
  // Leaflet's geodesic map.distance() at the bottom of the current viewport,
  // so it remains accurate as the user zooms and pans.
  function niceNmScale(maxNm) {
    if (!(maxNm > 0) || !isFinite(maxNm)) return 0;
    var power = Math.pow(10, Math.floor(Math.log(maxNm) / Math.LN10));
    var factors = [5, 2, 1];
    for (var i = 0; i < factors.length; i++) {
      var candidate = factors[i] * power;
      if (candidate <= maxNm) return candidate;
    }
    return power;
  }

  function formatNmScale(value) {
    if (value >= 10 || Math.round(value) === value) return String(value);
    if (value >= 1) return value.toFixed(1).replace(/\.0$/, "");
    return value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
  }

  var nmScaleControl = L.control({ position: "bottomright" });
  nmScaleControl.onAdd = function (mapInstance) {
    var container = L.DomUtil.create("div", "leaflet-control fiso-nm-scale");
    var label = L.DomUtil.create("div", "fiso-nm-scale-label", container);
    var bar = L.DomUtil.create("div", "fiso-nm-scale-bar", container);
    L.DomEvent.disableClickPropagation(container);

    function updateNmScale() {
      var size = mapInstance.getSize();
      if (!size || size.x <= 0 || size.y <= 0) return;

      // Release 280: make the nautical-mile scale span roughly half the usable
      // map width.  The distance is measured across that exact screen span, then
      // rounded only for the displayed label, keeping the visual scale accurate.
      var targetWidthPx = Math.max(160, Math.round(size.x * 0.48));
      targetWidthPx = Math.min(targetWidthPx, Math.max(160, size.x - 48));
      var y = Math.max(0, size.y - 28);
      var xRight = Math.max(targetWidthPx, size.x - 18);
      var xLeft = Math.max(0, xRight - targetWidthPx);
      var left = mapInstance.containerPointToLatLng([xLeft, y]);
      var right = mapInstance.containerPointToLatLng([xRight, y]);
      var exactNm = mapInstance.distance(left, right) / 1852;
      if (!(exactNm > 0) || !isFinite(exactNm)) return;

      var displayNm;
      if (exactNm >= 20) displayNm = Math.round(exactNm);
      else if (exactNm >= 2) displayNm = Math.round(exactNm * 2) / 2;
      else displayNm = Math.round(exactNm * 10) / 10;
      if (!(displayNm > 0)) displayNm = exactNm;

      var width = Math.max(1, Math.round(targetWidthPx * (displayNm / exactNm)));
      width = Math.min(Math.round(size.x * 0.52), width);
      bar.style.width = width + "px";
      label.textContent = formatNmScale(displayNm) + " NM";
    }

    nmScaleControl._updateNmScale = updateNmScale;
    mapInstance.on("zoomend moveend resize", updateNmScale);
    window.requestAnimationFrame(updateNmScale);
    return container;
  };
  nmScaleControl.onRemove = function (mapInstance) {
    if (nmScaleControl._updateNmScale) {
      mapInstance.off("zoomend moveend resize", nmScaleControl._updateNmScale);
    }
  };
  nmScaleControl.addTo(map);

  // DEV377 — on-map basemap brightness control.
  // Applies only to the map imagery pane (standard basemap / eVFR chart tiles),
  // leaving aircraft, NOTAMs, danger areas, labels and other operational overlays unchanged.
  var MAP_BRIGHTNESS_STORAGE_KEY = "fisoMapBrightness";
  // DEV415 — map brightness always starts at grade 5 (100%) on open/refresh.
  var mapBrightness = 100;

  function applyMapBrightness(value) {
    mapBrightness = Math.max(35, Math.min(140, parseInt(value, 10) || 100));
    var tilePane = map.getPane && map.getPane("tilePane");
    if (tilePane) tilePane.style.filter = "brightness(" + mapBrightness + "%)";
    // A just-uploaded eVFR preview is an ImageOverlay in overlayPane rather than tilePane.
    // Brighten/dim that image too, without affecting operational vector overlays.
    try {
      if (chartOverlayLayer && chartOverlayLayer.getElement) {
        var chartEl = chartOverlayLayer.getElement();
        if (chartEl && chartEl.tagName === "IMG") chartEl.style.filter = "brightness(" + mapBrightness + "%)";
      }
    } catch (e) {}
    try { localStorage.setItem(MAP_BRIGHTNESS_STORAGE_KEY, String(mapBrightness)); } catch (e) {}
  }


  // DEV410 — compact 1–9 brightness scale. Grade 5 is the normal 100% map brightness.
  function brightnessToGrade(value) {
    var v = Number(value);
    if (!isFinite(v)) v = 100;
    var levels = [60,70,80,90,100,110,120,130,140];
    var best = 4, dist = Infinity;
    levels.forEach(function(n,i){ var d=Math.abs(v-n); if(d<dist){dist=d;best=i;} });
    return best + 1;
  }
  function brightnessFromGrade(grade) {
    var levels = [60,70,80,90,100,110,120,130,140];
    var g = Math.max(1, Math.min(9, parseInt(grade,10) || 5));
    return levels[g-1];
  }

