        '</div>' +
        '<div class="fiso-layer-size fiso-layer-size-compact"><div><span>AIRCRAFT + TDB SIZE</span><b id="fisoTrafficSizeValue">' + (settings.trafficSize || settings.aircraftSize || 5) + '</b></div><input id="fisoTrafficSizeSlider" type="range" min="1" max="9" step="1" value="' + (settings.trafficSize || settings.aircraftSize || 5) + '" aria-label="Aircraft and TDB size"><div class="fiso-size-scale"><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span><span>8</span><span>9</span></div></div>' +
        '<div class="fiso-layer-brightness fiso-layer-brightness-compact"><div><span>MAP BRIGHTNESS</span><b id="mapBrightnessValue">' + brightnessToGrade(mapBrightness) + '</b></div>' +
          '<input id="mapBrightnessSlider" type="range" min="1" max="9" step="1" value="' + brightnessToGrade(mapBrightness) + '" aria-label="Map brightness grade" title="5 = default brightness"><div class="fiso-size-scale"><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span><span>8</span><span>9</span></div></div>' +
        '<div class="fiso-layer-foot"><button type="button" id="fisoLayersReset">RESET MAP</button><span>Operational overlays stay full brightness</span></div>' +
      '</div>';

    L.DomEvent.disableClickPropagation(box);
    L.DomEvent.disableScrollPropagation(box);

