    var latHem = box.querySelector("#fisoLatHem"), latDeg = box.querySelector("#fisoLatDeg"), latMin = box.querySelector("#fisoLatMin"), latSec = box.querySelector("#fisoLatSec");
    var lonHem = box.querySelector("#fisoLonHem"), lonDeg = box.querySelector("#fisoLonDeg"), lonMin = box.querySelector("#fisoLonMin"), lonSec = box.querySelector("#fisoLonSec");
    var positionGoDms = box.querySelector("#fisoPositionGoDms");
    var w3w1 = box.querySelector("#fisoW3W1"), w3w2 = box.querySelector("#fisoW3W2"), w3w3 = box.querySelector("#fisoW3W3");
    var w3wNote = box.querySelector("#fisoW3WNote");
    var positionGoW3w = box.querySelector("#fisoPositionGoW3w");
