    paraTimes[siteId] = { start: saved.start || "", finish: saved.finish || "", mode: "NOT_ACTIVE" };
    try { localStorage.setItem(LS_PARA, JSON.stringify(paraTimes)); } catch (e) {}
    if (typeof syncParaToFirebase === "function") syncParaToFirebase();
    applyParaOverrideUi(siteId);
