  function clearHazardPointLabels() {
    activeHazardPointLabels.forEach(function (lab) {
      try { hazardLayer.removeLayer(lab); } catch (e) {}
    });
    activeHazardPointLabels = [];
  }

  function addHazardPointLabels(h) {
    clearHazardPointLabels();
    if (!h.points || h.points.length < 2) return;
    h.points.forEach(function (p, i) {
      var lab = L.marker([p.lat, p.lon], {
        interactive: false,
        keyboard: false,
        icon: L.divIcon({
          className: 'haz-vertex-label-icon',
          html: hazardPointLabelHtml(p, i),
          iconSize: [92, 22],
          iconAnchor: [2, 20],
        }),
        zIndexOffset: 1400,
      });
      lab.addTo(hazardLayer);
      activeHazardPointLabels.push(lab);
    });
  }

  function showHazardPointLabelsOnSelect(h) {
    if (h && h.points && h.points.length > 1) addHazardPointLabels(h);
    else clearHazardPointLabels();
  }

  // Release193: popup selection is temporary for every plotted NOTAM, whether
  // created manually or by AUTO PIB plotting.  When its popup is dismissed,
  // rebuild the plotted NOTAM layers from their stored records so marker,
  // polygon/line, radius and any temporary vertex labels return to the exact
  // pre-selection operational appearance.
  function restorePlottedNotamAfterPopupClose() {
    clearHazardPointLabels();
    setTimeout(function () {
      try { renderHazards(); } catch (e) { console.warn("FFApp: unable to restore plotted NOTAM after popup close", e); }
    }, 0);
  }


  // Release194: HAZPLOT / plotted NOTAM popup architecture.
  var hazplotPopupLeader = null;
  var activeHazplotPopupId = null;
  var hazplotPopupSync = null;

  function hazardBoundsLatLng(h) {
    if (!h) return null;
    if (h.pointGroups && h.pointGroups.length) {
      var gp = [];
      h.pointGroups.forEach(function(g){
        (g && g.points || []).forEach(function(p){
          if (p && isFinite(Number(p.lat)) && isFinite(Number(p.lon))) gp.push([Number(p.lat),Number(p.lon)]);
        });
      });
      if (gp.length) return L.latLngBounds(gp);
    }
    if (h.points && h.points.length > 1) {
      var pts = h.points.filter(function(p){
        return p && isFinite(Number(p.lat)) && isFinite(Number(p.lon));
      }).map(function(p){ return [Number(p.lat), Number(p.lon)]; });
      if (pts.length) return L.latLngBounds(pts);
    }
    if (isFinite(Number(h.lat)) && isFinite(Number(h.lon))) {
      if (isRadiusHazardType(h.type) && h.hideRadius !== true) {
        var c = L.latLng(Number(h.lat), Number(h.lon));
        var rNm = Number(h.radiusNm) || 2.5;
        var dLat = (rNm * 1852) / 111320;
        var dLon = dLat / Math.max(0.2, Math.cos(c.lat * Math.PI / 180));
        return L.latLngBounds([c.lat-dLat,c.lng-dLon],[c.lat+dLat,c.lng+dLon]);
      }
      return L.latLngBounds([[Number(h.lat),Number(h.lon)],[Number(h.lat),Number(h.lon)]]);
    }
    return null;
  }

  function clearHazplotPopupLeader() {
    if (hazplotPopupLeader && map) {
      try { map.removeLayer(hazplotPopupLeader); } catch(e) {}
    }
    hazplotPopupLeader = null;
  }

  function clearHazplotPopupSync() {
    if (!hazplotPopupSync || !map) return;
    hazplotPopupSync.events.forEach(function(evt){
      try { map.off(evt, hazplotPopupSync.fn); } catch(e) {}
    });
    if (hazplotPopupSync.frame) cancelAnimationFrame(hazplotPopupSync.frame);
    hazplotPopupSync = null;
  }

  function drawHazplotPopupLeader(h) {
    clearHazplotPopupLeader();
    if (!map || !map._popup || !h) return;
    var popupEl = map._popup.getElement && map._popup.getElement();
    var mapEl = map.getContainer && map.getContainer();
    var b = hazardBoundsLatLng(h);
    if (!popupEl || !mapEl || !b) return;

    var pr = popupEl.getBoundingClientRect();
    var mr = mapEl.getBoundingClientRect();
    var startPt = L.point(pr.left - mr.left, ((pr.top + pr.bottom) / 2) - mr.top);
    // Release255: GNSS/GPS/radio-frequency jamming popups must point to the
    // black jamming PIN, not to the centre of the published polygon. Other
    // plotted NOTAM types retain the existing area-centre leader target.
    var targetLL = isGnssJammingHazard(h) && isFinite(Number(h.lat)) && isFinite(Number(h.lon))
      ? L.latLng(Number(h.lat), Number(h.lon))
      : b.getCenter();
    var targetPt = map.latLngToContainerPoint(targetLL);
    var startLL = map.containerPointToLatLng(startPt);
    var angle = Math.atan2(targetPt.y-startPt.y, targetPt.x-startPt.x) * 180 / Math.PI;

    var line = L.polyline([startLL,targetLL], {
      color:"#111", weight:2.5, opacity:1, interactive:false, pane:"overlayPane"
    });
    var head = L.marker(targetLL, {
      interactive:false, keyboard:false, pane:"markerPane",
      icon:L.divIcon({
        className:"hazdam-popup-arrowhead-wrap",
        html:'<span class="hazdam-popup-arrowhead" style="transform:rotate(' + angle + 'deg)"></span>',
        iconSize:[18,18], iconAnchor:[9,9]
      })
    });
    hazplotPopupLeader = L.layerGroup([line,head]).addTo(map);
  }

  function openHazplotPopup(h) {
    if (!map || !window.L || !h) return;
    clearHazplotPopupLeader();
    clearHazplotPopupSync();
    activeHazplotPopupId = String(h.id);

    var bounds = hazardBoundsLatLng(h);
    var centre = bounds ? bounds.getCenter() : L.latLng(Number(h.lat),Number(h.lon));
    var where = centre;
    if (bounds) {
      var east = L.latLng(centre.lat,bounds.getEast());
      var ep = map.latLngToLayerPoint(east);
      where = map.layerPointToLatLng(L.point(ep.x+284,ep.y));
    }

    var popup = L.popup({
      autoPan:true, autoPanPadding:[36,36], closeButton:true,
      minWidth:420, maxWidth:520,
      className:"hazdam-info-popup hazdam-info-popup-right hazplot-info-popup"
    }).setLatLng(where).setContent(hazardPopupHtml(h)).openOn(map);

    setTimeout(function(){
      var el=popup.getElement&&popup.getElement(); if(!el||el.dataset.dragWired==="1")return; el.dataset.dragWired="1";
      var wrap=el.querySelector(".leaflet-popup-content-wrapper")||el, drag=null;
      wrap.addEventListener("pointerdown",function(e){
        if(e.button!==undefined&&e.button!==0)return; if(e.target.closest("a,button,input,select,textarea,label"))return;
        var pt=map.latLngToLayerPoint(popup.getLatLng()); drag={id:e.pointerId,x:e.clientX,y:e.clientY,pt:pt}; el.classList.add("notam-popup-dragging");
        try{wrap.setPointerCapture(e.pointerId);}catch(_){} e.preventDefault(); e.stopPropagation();
      });
      wrap.addEventListener("pointermove",function(e){if(!drag||e.pointerId!==drag.id)return; popup.setLatLng(map.layerPointToLatLng(L.point(drag.pt.x+e.clientX-drag.x,drag.pt.y+e.clientY-drag.y))); drawHazplotPopupLeader(h); e.preventDefault(); e.stopPropagation();});
      function end(e){if(!drag||(e.pointerId!==undefined&&e.pointerId!==drag.id))return; drag=null;el.classList.remove("notam-popup-dragging");e.stopPropagation();}
      wrap.addEventListener("pointerup",end);wrap.addEventListener("pointercancel",end);
    },0);

    setTimeout(function(){
      if (!map || map._popup !== popup || !bounds) return;
      var el = popup.getElement && popup.getElement();
      if (el) {
        var ph = el.getBoundingClientRect().height;
        var cp = map.latLngToLayerPoint(centre);
        var pp = map.latLngToLayerPoint(popup.getLatLng());
        popup.setLatLng(map.layerPointToLatLng(L.point(pp.x,cp.y+ph/2)));
      }
      setTimeout(function(){
        if (map && map._popup === popup) drawHazplotPopupLeader(h);
      },0);
    },0);

    var events = ["zoom","zoomend","move","moveend","resize"];
    var sync = function(){
      if (!map || map._popup !== popup) return;
      if (hazplotPopupSync && hazplotPopupSync.frame) cancelAnimationFrame(hazplotPopupSync.frame);
      if (hazplotPopupSync) {
        hazplotPopupSync.frame = requestAnimationFrame(function(){
          if (hazplotPopupSync) hazplotPopupSync.frame = 0;
          if (map && map._popup === popup) drawHazplotPopupLeader(h);
        });
      }
    };
    hazplotPopupSync = {fn:sync,events:events,frame:0};
    events.forEach(function(evt){ map.on(evt,sync); });

    popup.once("remove",function(){
      var closingId = String(h.id);
      clearHazplotPopupSync();
      clearHazplotPopupLeader();
      if (isGnssJammingHazard(h)) keepGnssJammingAreaAfterPopup(h);
      if (isAerialFilmingHazard(h)) keepAerialFilmingAreaAfterPopup(h);
      if (activeHazplotPopupId === closingId) {
        activeHazplotPopupId = null;
        clearHazardPointLabels();
        setTimeout(function(){
          if (activeHazplotPopupId == null) renderHazards();
        },0);
      }
    });
  }

  function redArrowsBearingDeg(a,b) {
    var p1=Number(a.lat)*Math.PI/180, p2=Number(b.lat)*Math.PI/180;
    var dl=(Number(b.lon)-Number(a.lon))*Math.PI/180;
    var y=Math.sin(dl)*Math.cos(p2);
    var x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl);
    return (Math.atan2(y,x)*180/Math.PI+360)%360;
  }

  function redArrowsLegPhase(leg, nowMs) {
    var st=new Date(leg.start.timeISO).getTime(), en=new Date(leg.end.timeISO).getTime();
    if (!isFinite(st)||!isFinite(en)) return "hidden";
    if (nowMs < st-15*60000 || nowMs > en+5*60000) return "hidden";
    if (nowMs < st-5*60000) return "flash";
    return "solid";
  }

  function renderRedArrowsRouteHazard(h) {
    var group=L.layerGroup().addTo(hazardLayer), now=window.ffappNowMs ? window.ffappNowMs() : Date.now(), visible=0;
    var visibleWaypoints=[], seenWaypoints={};

    function rememberWaypoint(pt) {
      if (!pt) return;
      var key=[Number(pt.lat).toFixed(5),Number(pt.lon).toFixed(5),String(pt.time||""),String(pt.name||"")].join("|");
      if (seenWaypoints[key]) return;
      seenWaypoints[key]=true;
      visibleWaypoints.push(pt);
    }

    (h.routeLegs||[]).forEach(function(leg){
      var phase=redArrowsLegPhase(leg,now);
      if(hazardIsNotamPlot(h)&&!todayHazardsEnabled&&hazardState(h)==="hidden")phase="hidden";
      if(todayHazardsEnabled&&hazardIsNotamPlot(h)){
        var win=todayUtcWindow(window.ffappNowMs?window.ffappNowMs():Date.now()),st=Date.parse(leg.start.timeISO),en=Date.parse(leg.end.timeISO);
        phase=todayNotamOverlaps(h,window.ffappNowMs?window.ffappNowMs():Date.now())&&isFinite(st)&&isFinite(en)&&st<=win.end&&en>=win.start?"solid":"hidden";
      }
      if (phase === "hidden") return;
      visible++;
      rememberWaypoint(leg.start);
      rememberWaypoint(leg.end);

      var a=[leg.start.lat,leg.start.lon], b=[leg.end.lat,leg.end.lon];
      var col=phase === "flash" ? "#ff7777" : "#e60000";
      var line=L.polyline([a,b],{color:col,weight:3,opacity:0.92,className:phase === "flash" ? "red-arrows-leg red-arrows-leg-flash" : "red-arrows-leg"});
      line.on("click",function(){ openHazplotPopup(h); });
      line.addTo(group);

      var mid={lat:(leg.start.lat+leg.end.lat)/2,lon:(leg.start.lon+leg.end.lon)/2};
      var bearing=redArrowsBearingDeg(leg.start,leg.end);
      var arrow=L.marker([mid.lat,mid.lon],{interactive:false,keyboard:false,icon:L.divIcon({className:"",iconSize:[18,18],iconAnchor:[9,9],html:'<div class="red-arrows-direction '+(phase === "flash" ? 'red-arrows-leg-flash' : '')+'" style="color:'+col+';transform:rotate('+(bearing-90)+'deg)">➤</div>'})});
      arrow.addTo(group);
    });

    // Release245: waypoint labels replace the large leg-centre banners. They are
    // deliberately hidden at wider map scales and appear only after the operator
    // zooms in, so the UK/regional view remains readable.
    var directions=["top","right","bottom","left"];
    visibleWaypoints.forEach(function(pt,idx){
      var marker=L.circleMarker([pt.lat,pt.lon],{radius:2.6,color:"#d90000",weight:1.5,fillColor:"#ff3a3a",fillOpacity:1,interactive:false});
      marker.addTo(group);
      var labelHtml='<span class="red-arrows-waypoint-time">'+esc(String(pt.time||""))+'</span><span class="red-arrows-waypoint-name" title="'+esc(String(pt.name||""))+'">'+esc(String(pt.name||""))+'</span>';
      marker.bindTooltip(labelHtml,{permanent:true,direction:directions[idx%directions.length],offset:[0,-1],opacity:1,className:"red-arrows-waypoint-tooltip",interactive:false});
      marker.openTooltip();
    });

    try { updateRedArrowsLabelZoomState(); } catch(_e) {}
    hazardShapes[h.id]=group;
    return visible;
  }

  function updateRedArrowsLabelZoomState() {
    if (!map || !map.getContainer) return;
    var el=map.getContainer();
    var show=Number(map.getZoom()) >= 9;
    el.classList.toggle("red-arrows-labels-visible",show);
    el.classList.toggle("red-arrows-labels-hidden",!show);
    // DEV246: the moving Red Arrows aircraft uses the same close-zoom threshold
    // as the waypoint time/location labels.
    try { updateRedArrowsPlanes(); } catch(_e) {}
  }

  // Release248: moving Red Arrows aircraft across ALL timed transit legs.
  // Each Red Arrows route gets its own small aircraft marker. The marker appears
  // only while the operational/test UTC clock is between a leg's published start
  // and end times, then hands over seamlessly to the next leg at the waypoint.
  // Aircraft markers use the same close-zoom threshold (zoom >= 9) as the
  // waypoint time/location labels.
  var redArrowsPlaneMarkers={};

  function redArrowsRouteKey(h,idx){
    return String((h&&h.id)||((h&&h.autoKey)||"red-arrows-route-"+idx));
  }

  function findActiveRedArrowsLeg(route,now){
    if(!route||!Array.isArray(route.routeLegs))return null;
    var legs=route.routeLegs;
    for(var i=0;i<legs.length;i++){
      var leg=legs[i];
      if(!leg||!leg.start||!leg.end)continue;
      var st=new Date(leg.start.timeISO).getTime(), en=new Date(leg.end.timeISO).getTime();
      if(!isFinite(st)||!isFinite(en)||en<=st)continue;
      // Use a half-open interval so the exact shared waypoint time belongs to
      // the following leg. The final route endpoint remains visible at progress 1.
      var isLast=(i===legs.length-1);
      if(now>=st && (now<en || (isLast&&now===en)))return leg;
    }
    return null;
  }

  function removeRedArrowsPlaneMarker(key){
    var marker=redArrowsPlaneMarkers[key];
    if(marker){
      try{if(map&&map.hasLayer&&map.hasLayer(marker))map.removeLayer(marker);}catch(_e){}
      delete redArrowsPlaneMarkers[key];
    }
  }

  function removeAllRedArrowsPlaneMarkers(){
    Object.keys(redArrowsPlaneMarkers).forEach(removeRedArrowsPlaneMarker);
  }

  function updateRedArrowsPlanes(){
    if(!map||Number(map.getZoom())<9){removeAllRedArrowsPlaneMarkers();return;}
    var now=window.ffappNowMs?window.ffappNowMs():Date.now();
    var routes=(hazards||[]).filter(function(h){
      return h&&h.areaStyle==="RED_ARROWS_TRANSIT"&&Array.isArray(h.routeLegs)&&h.routeLegs.length;
    });
    var keep={};

    routes.forEach(function(route,routeIndex){
      var key=redArrowsRouteKey(route,routeIndex);
      var leg=findActiveRedArrowsLeg(route,now);
      if(!leg){removeRedArrowsPlaneMarker(key);return;}

      var st=new Date(leg.start.timeISO).getTime(), en=new Date(leg.end.timeISO).getTime();
      var progress=Math.max(0,Math.min(1,(now-st)/(en-st)));
      var lat=Number(leg.start.lat)+(Number(leg.end.lat)-Number(leg.start.lat))*progress;
      var lon=Number(leg.start.lon)+(Number(leg.end.lon)-Number(leg.start.lon))*progress;
      var bearing=redArrowsBearingDeg(leg.start,leg.end);
      var html='<div class="red-arrows-plane-wrap" style="transform:rotate('+(bearing+90)+'deg)"><img src="red-arrows-plane.png" alt=""></div>';
      var icon=L.divIcon({className:"red-arrows-plane-marker",iconSize:[22,18],iconAnchor:[11,9],html:html});
      var marker=redArrowsPlaneMarkers[key];

      if(!marker){
        marker=L.marker([lat,lon],{interactive:false,keyboard:false,zIndexOffset:1600,icon:icon});
        marker.addTo(map);
        redArrowsPlaneMarkers[key]=marker;
      }else{
        marker.setLatLng([lat,lon]);
        marker.setIcon(icon);
        if(map.hasLayer&&!map.hasLayer(marker))marker.addTo(map);
      }
      keep[key]=true;
    });

    Object.keys(redArrowsPlaneMarkers).forEach(function(key){
      if(!keep[key])removeRedArrowsPlaneMarker(key);
    });
  }

  if(!window.__ffappRedArrowsPlaneTimer){
    window.__ffappRedArrowsPlaneTimer=setInterval(function(){try{updateRedArrowsPlanes();}catch(_e){}},250);
  }

  function renderHazards() {
    setTimeout(refreshNotamPlotReferences,0);
    // Release243: ensure Red Arrows routes exist before evaluating timed legs.
    // This is especially important after ADMIN forwards the operational clock.
    try { ensureRedArrowsTransitHazardsFromCurrentPib(); } catch(e) { console.warn("Red Arrows route repair failed", e); }
    // Release226: Firebase sync can replace the local hazard array after startup.
    // Re-attach the static SUP AIP 101/26 architecture before each render.
    ensureSup101TemporaryDangerAreas();
    if (ensureHazardIds(hazards)) saveJSON(LS_KEY_HAZARDS, hazards);
    clearHazardPointLabels();
    hazardLayer.clearLayers();
    hazardMarkers = {};
    hazardShapes = {};
    hazardRadiusShapes = {};
    var listEl = document.getElementById("hazList");
    document.getElementById("hazCount").textContent = hazards.length;
    if (!hazards.length) {
      listEl.innerHTML = '<p class="empty-note">No hazards plotted yet.</p>';
    } else {
      listEl.innerHTML = hazards
        .slice()
        .sort(function (a, b) {
          return a.startISO < b.startISO ? -1 : 1;
        })
        .map(function (h) {
          return (
            '<div class="list-item" data-id="' +
            h.id +
            '">' +
            '<div class="li-top"><span class="li-name">' +
            esc(hazardDisplayLabel(h)) +
            " #" +
            esc(hazardManualReferences(h).pin) +
            (function(){
              var nid = String(h.autoKey || "").toUpperCase() || autoPibNotamId(h.notam);
              if (!nid) return "";
              var pg = hazardManualReferences(h).page || h.sourcePage || currentPibSourcePage(nid);
              return ' <span class="haz-source-ref">(' + esc(nid) + (pg ? ' page ' + esc(String(pg)) : '') + ')</span>';
            })() +
            (h.autoSource === "PIB" ? " &middot; AUTO PIB" : "") +
            (h.points && h.points.length > 1 ? " (area &middot; " + h.points.length + " pts)" : "") +
            "</span></div>" +
            '<div class="li-meta">' +
            (isAlwaysVisibleRadiusHazardType(h.type) ? "Radius " + esc(String(h.radiusNm || 2.5)) + " NM" : (hazardIsNotamPlot(h)&&!isFrenchSupplementOverlay(h)&&(!h.startISO||!h.finishISO) ? "Validity requires checking" : h.alwaysActive || !h.startISO || !h.finishISO ? "No times – active until deleted" : (fmtHazTime(h.startISO) + " &rarr; " + fmtHazTime(h.finishISO)))) +
            "</div>" +
            (h.scheduleD ? '<div class="li-meta"><b>D)</b> ' + esc(String(h.scheduleD)) + '</div>' : '') + hazardScheduleBadge(h) +
            (isAlwaysVisibleRadiusHazardType(h.type) ? "" : ('<div class="li-meta">' +
            esc(h.lower || "\u2013") +
            " &ndash; " +
            esc(h.upper || "\u2013") +
            "</div>")) +
            (function(){
              var nid = String(h.autoKey || "").toUpperCase() || autoPibNotamId(h.notam);
              if (!nid) return "";
              var pg = hazardManualReferences(h).page || h.sourcePage || currentPibSourcePage(nid);
              return '<div class="haz-plotted-status"><span class="haz-plotted-code">' + esc(nid) + '</span>' +
                '<span class="haz-plotted-pin">plotted pin ' + esc(hazardManualReferences(h).pin) + '</span>' +
                (pg ? '<span class="haz-plotted-page">(page ' + esc(String(pg)) + ')</span>' : '') +
                '</div>';
            })() +
            '<div class="li-actions">' +
            '<button class="btn" data-act="fly" data-id="' +
            h.id +
            '">Go to</button>' +
            '<button class="btn" data-act="edit" data-id="' +
            h.id +
            '">Edit</button>' +
            '<button class="btn danger" data-act="del" data-id="' +
            h.id +
            '">Delete</button>' +
            "</div></div>"
          );
        })
        .join("");
    }
    var hideLowNotams = filterPlottedNotamsBelow1000Enabled();
    var renderedAutoHazards = Object.create(null);
    hazards.forEach(function (h) {
      // The 1000 ft switch is a map-display filter only. Apply it to the
      // AUTO PIB hazard layer as well as the generic NOTAM layer.
      if (hideLowNotams && hazardIsNotamPlot(h) && notamPlotIsBelow1000Ft(h.lower, h.upper)) return;

      // Guard against duplicate AUTO records (for example after sync/rebuild).
      // Keep genuinely different products from one NOTAM, but render an exact
      // same-type/same-position/same-geometry product only once.
      if (hazardIsNotamPlot(h)) {
        var dupNid = String(h.autoKey || h.notamId || "").toUpperCase().trim() || autoPibNotamId(h.notam);
        if (dupNid) {
          var ptsKey = Array.isArray(h.points) ? h.points.map(function(p){ return Number(p.lat).toFixed(5) + "," + Number(p.lon).toFixed(5); }).join(";") : "";
          var dupKey = [dupNid, String(h.type || "").toLowerCase(), Number(h.lat).toFixed(5), Number(h.lon).toFixed(5), String(h.radiusNm || ""), String(h.areaStyle || ""), ptsKey].join("|");
          if (renderedAutoHazards[dupKey]) return;
          renderedAutoHazards[dupKey] = true;
        }
      }

      if (h.areaStyle === "RED_ARROWS_TRANSIT" && Array.isArray(h.routeLegs)) {
        renderRedArrowsRouteHazard(h);
        return;
      }
      // Release206: D098 complex uses the permanent Danger Area architecture only.
      // Never render a TDA pin for D098, including legacy/persisted records.
      var d098Tda = String(h.type || "").toLowerCase() === "tda" &&
        /\b(?:EG)?D098[A-Z]?\b/i.test((String(h.displayLabel || "") + " " + String(h.notam || "") + " " + String(h.autoKey || "")));
      var pinCol = h.plotColor || HAZ_PIN_COLORS[h.type] || "var(--green)";
      // DEV340: reference numbers above black MISC pins are always black.
      var pinRefCol = String(h.type || "").toLowerCase() === "misc" ? "#000000" : pinCol;
      var icon = L.divIcon({
        className: "",
        iconSize: [22, 46],
        iconAnchor: [11, 46],
        html:
          '<div class="hazard-pin" style="position:relative;display:flex;flex-direction:column;align-items:center;">' +
          '<div style="width:' + Math.max(18,Math.min(84,hazardManualReferences(h).pin.length*6+6)) + 'px;height:18px;border-radius:50%;border:2px solid ' +
          pinRefCol +
          ";color:" +
          pinRefCol +
          ';font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;font-family:monospace;flex-shrink:0;">' +
          esc(hazardManualReferences(h).pin) +
          "</div>" +
          hazardPinSvg(pinCol, h.type) +
          "</div>",
      });
      var canDragPin = hazEditing === h.id && !(h.points && h.points.length > 1);
      var m = L.marker([h.lat, h.lon], { icon: icon, zIndexOffset: 5000, draggable: canDragPin });
      m.on("click", function () {
        // Release249: for GNSS/GPS/radio-frequency jamming the published area
        // is revealed only when the operator deliberately clicks the pin.
        if (isGnssJammingHazard(h)) {
          setGnssJammingAreaOpen(h);
          try { renderGnssJammingAreaHighlight(h); } catch(_e) {}
        }
        // Dev328: Aerial Filming is a temporary situational area. Reveal the
        // light-yellow published polygon only from its numbered pin.
        if (isAerialFilmingHazard(h)) {
          setAerialFilmingAreaOpen(h);
          try { renderAerialFilmingAreaHighlight(h); } catch(_e) {}
        }
        showHazardPointLabelsOnSelect(h);
        openHazplotPopup(h);
      });
      m.on("contextmenu", function (ev) {
        if (ev.originalEvent) {
          ev.originalEvent.preventDefault();
          ev.originalEvent.stopPropagation();
        }
        var pt = ev.originalEvent || { clientX: 0, clientY: 0 };
        showFfContextMenu(pt.clientX || 0, pt.clientY || 0, [
          { label: "Edit", run: function () { editHazardById(h.id); } },
          { label: "Delete", danger: true, run: function () { deleteHazardById(h.id); } },
        ]);
      });
      m.on("drag", function (ev) {
        var ll = ev.target.getLatLng();
        h.lat = ll.lat;
        h.lon = ll.lng;
        if (hazardRadiusShapes[h.id]) hazardRadiusShapes[h.id].setLatLng(ll);
        if (hazEditing === h.id) updateHazLatLonInputs(ll.lat, ll.lng);
      });
      m.on("dragend", function (ev) {
        var ll = ev.target.getLatLng();
        h.lat = ll.lat;
        h.lon = ll.lng;
        hazards = hazards.map(function (x) { return String(x.id) === String(h.id) ? h : x; });
        saveJSON(LS_KEY_HAZARDS, hazards);
        if (hazEditing === h.id) updateHazLatLonInputs(ll.lat, ll.lng);
        renderHazards();
      });
      if (!d098Tda && h.suppressPin !== true) {
        m.addTo(hazardLayer);
        hazardMarkers[h.id] = m;
      }

      if (isRadiusHazardType(h.type) && h.hideRadius !== true && !d098Tda) {
        var rNm = Number(h.radiusNm) || 2.5;
        var circle = L.circle([h.lat, h.lon], {
          radius: rNm * 1852,
          color: pinCol,
          weight: 2,
          opacity: 0.85,
          fillColor: pinCol,
          fillOpacity: 0.08,
          dashArray: "6 4",
          interactive: false,
        });
        circle.addTo(hazardLayer);
        hazardRadiusShapes[h.id] = circle;
        if (circle.bringToBack) circle.bringToBack();
      }

      function renderGnssJammingAreaHighlight(hh) {
        if (!hh || !isGnssJammingHazard(hh)) return null;
        var id = String(hh.id);
        try {
          if (hazardShapes[id] && hazardLayer) hazardLayer.removeLayer(hazardShapes[id]);
        } catch(_e) {}
        var infoFill = hh.areaStyle === "INFO_EXERCISE" ? "#d71920" : "#8f969d";
        var layers = [];

        // Release260: preserve separate AREA 1/2/3/4 polygons from multi-area
        // fighter-training NOTAMs. Add small AREA labels while selected.
        if (hh.areaStyle === "INFO_EXERCISE" && hh.pointGroups && hh.pointGroups.length) {
          hh.pointGroups.forEach(function(g){
            var raw = (g && g.points) || [];
            if (raw.length < 2) return;
            var pts = raw.map(function(p){ return [p.lat,p.lon]; });
            var sh = raw.length >= 3
              ? L.polygon(pts, { color:"#d71920", weight:2, opacity:0.95, fillColor:infoFill, fillOpacity:0.38, interactive:false })
              : L.polyline(pts, { color:infoFill, weight:2, opacity:0.95, interactive:false });
            layers.push(sh);
            if (raw.length >= 3 && g.label) {
              var b = L.latLngBounds(pts);
              layers.push(L.marker(b.getCenter(), {
                interactive:false, keyboard:false,
                icon:L.divIcon({ className:"", iconSize:null, html:'<div style="font:700 12px monospace;color:#fff;background:rgba(180,0,0,.72);border:1px solid #fff;border-radius:3px;padding:1px 4px;white-space:nowrap;text-shadow:0 1px 1px #000;">' + esc(g.label) + '</div>' })
              }));
            }
          });
        } else if (hh.points && hh.points.length > 1) {
          var pts = hh.points.map(function(p){ return [p.lat,p.lon]; });
          layers.push(hh.points.length >= 3
            ? L.polygon(pts, { stroke:false, fillColor:infoFill, fillOpacity:0.55, interactive:false })
            : L.polyline(pts, { color:infoFill, weight:1, opacity:0.70, interactive:false }));
        }
        if (!layers.length && hh.areaStyle === "GNSS_JAMMING" && Number(hh.radiusNm) > 0) {
          layers.push(L.circle([hh.lat,hh.lon], {radius:Number(hh.radiusNm)*1852,stroke:false,fillColor:infoFill,fillOpacity:0.35,interactive:false}));
        }
        if (!layers.length) return null;
        var group = L.featureGroup(layers).addTo(hazardLayer);
        layers.forEach(function(x){ if (x.bringToBack && !(x instanceof L.Marker)) x.bringToBack(); });
        hazardShapes[id] = group;
        return group;
      }

      if (h.areaStyle === "GNSS_JAMMING" && !(h.points && h.points.length > 1) && Number(h.radiusNm) > 0 && gnssJammingAreaShouldShow(h)) renderGnssJammingAreaHighlight(h);

      function renderAerialFilmingAreaHighlight(hh) {
        if (!hh || !isAerialFilmingHazard(hh) || !hh.points || hh.points.length < 2) return null;
        var id = String(hh.id);
        try {
          if (hazardShapes[id] && hazardLayer) hazardLayer.removeLayer(hazardShapes[id]);
        } catch(_e) {}
        var pts = hh.points.map(function(p){ return [p.lat, p.lon]; });
        var sh = hh.points.length >= 3
          ? L.polygon(pts, {
              color:"#d7a900", weight:1.5, opacity:0.78,
              fillColor:"#ffd84a", fillOpacity:0.20, interactive:false
            })
          : L.polyline(pts, { color:"#d7a900", weight:2, opacity:0.78, interactive:false });
        sh.addTo(hazardLayer);
        if (sh.bringToBack) sh.bringToBack();
        hazardShapes[id] = sh;
        return sh;
      }

      // Multi-point NOTAM: draw the area as one polygon (or a line for
      // two points) with the numbered pin sitting at its centre.
      if (h.points && h.points.length > 1) {
        var latlngs = h.points.map(function (p) {
          return [p.lat, p.lon];
        });
        var isAerialSurveyShape = hazardDisplayLabel(h) === "Aerial Survey" || /\bAERIAL\s+SURVEY\s+ROUTING\b/i.test(String(h.notam || ""));
        var isAerialFilmingShape = isAerialFilmingHazard(h);
        var isInfoExerciseShape = h.areaStyle === "INFO_EXERCISE";
        var isGnssJammingShape = h.areaStyle === "GNSS_JAMMING" || isInfoExerciseShape ||
          /\bGNSS\b[\s\S]{0,80}\b(?:JAMMING|SPOOF(?:ING|NIG))\b/i.test(String(h.notam || ""));

        // Aerial Survey uses Display yellow. GNSS/GPS jamming is situational
        // information only: retain the black Misc pin, but show the published
        // multi-point area as light-grey shading with NO border/outline.
        var shapeStroke = isAerialSurveyShape
          ? (HAZ_PIN_COLORS.display || "var(--yellow)")
          : pinCol;
        var shapeFill = isAerialSurveyShape
          ? "#fff3a6"
          : (isInfoExerciseShape ? "#d71920" : (isGnssJammingShape ? "#8f969d" : pinCol));
        var isTempoCtaShape = h.areaStyle === "TEMPO_CTA";
        var isMultipleDisplayShape = h.areaStyle === "MULTIPLE_DISPLAY";
        if (isTempoCtaShape) {
          shapeStroke = "#1683ff";
          shapeFill = "#1683ff";
        }
        if (isMultipleDisplayShape) {
          shapeStroke = "#d7a900";
          shapeFill = "#ffd84a";
        }
        // TEMPO CTA and Multiple Display overlays stay translucent so aircraft
        // symbols and TDBs remain visually dominant above them.
        var shapeFillOpacity = isTempoCtaShape ? 0.055 :
          (isMultipleDisplayShape ? 0.10 :
          (isAerialSurveyShape ? 0.22 :
          (isGnssJammingShape ? 0.55 :
          (h.areaStyle === "SUP101" ? 0.16 : 0.12))));
        // Release249: GNSS/GPS/radio-frequency jamming areas are hidden until
        // their black pin is clicked. The grey boundary itself is deliberately
        // non-interactive, so it can never open the popup. Other multi-point
        // hazard types retain their existing click/context-menu behaviour.
        if (isAerialFilmingShape) {
          // Hidden by default; pin click shows the published area temporarily.
          if (aerialFilmingAreaShouldShow(h)) renderAerialFilmingAreaHighlight(h);
        } else if (isGnssJammingShape) {
          if (gnssJammingAreaShouldShow(h)) renderGnssJammingAreaHighlight(h);
        } else {
          var shape =
            h.points.length >= 3
              ? L.polygon(latlngs, {
                  color: shapeStroke,
                  weight: isTempoCtaShape ? 1.5 : (isMultipleDisplayShape ? 1.6 : (h.areaStyle === "SUP101" ? 3 : 2)),
                  opacity: isTempoCtaShape ? 0.55 : (isMultipleDisplayShape ? 0.78 : 0.9),
                  fillColor: shapeFill,
                  fillOpacity: shapeFillOpacity,
                  className: isTempoCtaShape ? "tempo-cta-shape" : (isMultipleDisplayShape ? "multiple-display-shape" : "")
                })
              : L.polyline(latlngs, { color: shapeStroke, weight: 2, opacity: 0.9 });
          shape.on("click", function () {
            showHazardPointLabelsOnSelect(h);
            openHazplotPopup(h);
          });
          shape.on("contextmenu", function (ev) {
            if (ev.originalEvent) { ev.originalEvent.preventDefault(); ev.originalEvent.stopPropagation(); }
            var pt = ev.originalEvent || { clientX: 0, clientY: 0 };
            showFfContextMenu(pt.clientX || 0, pt.clientY || 0, [
              { label: "Edit", run: function () { editHazardById(h.id); } },
              { label: "Delete", danger: true, run: function () { deleteHazardById(h.id); } },
            ]);
          });
          shape.addTo(hazardLayer);
          if (!isTempoCtaShape && !isMultipleDisplayShape && shape.bringToFront) shape.bringToFront();
          if ((isTempoCtaShape || isMultipleDisplayShape) && shape.bringToBack) shape.bringToBack();
          hazardShapes[h.id] = shape;
        }
      }

      // Release227: SUP AIP 101/26 areas are annotated like the D098 complex:
      // small red map text showing the area identifier and vertical limits.
      // These are labels only, not hazard pins, and do not participate in
      // HAZPLOT/HAZBUF logic.
      if (h.areaStyle === "SUP101" && h.mapTextLabel) {
        var supLabelHtml =
          '<div style="color:#ff3030;font:700 7px/0.95 monospace;text-align:center;' +
          'white-space:nowrap;text-shadow:0 0 1px #fff;letter-spacing:-0.25px;">' +
          esc(String(h.mapTextLabel)) + '<br>' +
          esc(String(h.mapLabelUpper || h.upper || "")) + '<br>' +
          esc(String(h.mapLabelLower || h.lower || "")) + '</div>';
        var supLabelIcon = L.divIcon({
          className: "",
          html: supLabelHtml,
          iconSize: [58, 24],
          iconAnchor: [29, 12]
        });
        L.marker([Number.isFinite(Number(h.mapLabelLat)) ? Number(h.mapLabelLat) : h.lat, Number.isFinite(Number(h.mapLabelLon)) ? Number(h.mapLabelLon) : h.lon], {
          icon: supLabelIcon,
          interactive: false,
          keyboard: false,
          zIndexOffset: 4200
        }).addTo(hazardLayer);
      }
    });
    refreshHazardVisibility();
    // DEV337: Leaflet marker DOM nodes may not exist synchronously on the first
    // render or immediately after ADMIN changes the operational clock. Re-apply
    // visibility after Leaflet has painted so a valid 30-minute/active pin never
    // remains hidden until the 20-second maintenance timer.
    try { requestAnimationFrame(function(){ refreshHazardVisibility(); }); } catch(_e) {}
    setTimeout(function(){ try { refreshHazardVisibility(); } catch(_e) {} }, 80);
    try {
      var hzSearch = document.getElementById("hazNotamCode");
      updateHazNotamSuggestions(hzSearch ? hzSearch.value : "");
    } catch (e) {}
  }

  document.getElementById("hazList").addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-act]");
    if (!btn) return;
    var id = btn.getAttribute("data-id");
    var act = btn.getAttribute("data-act");
    if (act === "del") {
      deleteHazardById(id);
      return;
    }
    var h = findHazardById(id);
    if (!h) return;
    if (act === "fly") {
      map.panTo([h.lat, h.lon]);
    } else if (act === "edit") {
      editHazardById(id);
    }
  });

  document.getElementById("hazCoord").addEventListener("input", function () {
    var m = this.value.trim().toUpperCase().match(HAZ_COORD_RE);
    if (!m) return;
    var latDeg = parseInt(m[1], 10),
      latMin = parseInt(m[2], 10),
      ns = m[3];
    var lonDeg = parseInt(m[4], 10),
      lonMin = parseInt(m[5], 10),
      ew = m[6];
    var lat = latDeg + latMin / 60;
    if (ns === "S") lat = -lat;
    var lon = lonDeg + lonMin / 60;
    if (ew === "W") lon = -lon;
    if (hazMultiMode) {
      hazFillNextEmptyRow(lat, lon);
      this.value = "";
      return;
    }
    document.getElementById("hazLat").value = decToDDM(lat, true);
    document.getElementById("hazLon").value = decToDDM(lon, false);
    if (typeof updateHazDms === "function") updateHazDms();
  });
  function applyHazardNotamText(text, updateCode) {
    var data = parseNotamForHazard(text || "");

    if (hazMultiMode) {
      var pts = parseNotamAllCoords(text || "");
      if (pts.length) fillHazPtRows(pts);
    }

    if (data.lat !== null)
      document.getElementById("hazLat").value = decToDDM(data.lat, true);

    if (data.lon !== null)
      document.getElementById("hazLon").value = decToDDM(data.lon, false);

    if (data.lower) document.getElementById("hazLower").value = data.lower;

    if (data.upper) document.getElementById("hazUpper").value = data.upper;

    if (data.start) document.getElementById("hazStart").value = data.start;

    if (data.finish) document.getElementById("hazFinish").value = data.finish;

    if (updateCode) {
      var codeMatch = String(text || "").match(/([A-Z]\d{3,4}\/\d{2})/i);
      if (codeMatch) document.getElementById("hazNotamCode").value = codeMatch[1].toUpperCase();
    }
  }

  // ✅ AUTO-FILL FROM NOTAM TEXT
  document.getElementById("hazNotam").addEventListener("input", function () {
    applyHazardNotamText(this.value, true);
  });

  function setHazNotamCodeStatus(msg, isError) {
    var el = document.getElementById("hazNotamCodeStatus");
    if (!el) return;
    el.textContent = msg || "";
    el.style.color = isError ? "var(--red)" : "var(--green)";
  }

  // Release143: derive/repair PIB PDF page numbers inside FISOFID.
  // Some shared PIB publishers pre-date sourcePage and therefore send the
  // NOTAM text without an explicit page field.  NATS PIB PDFs carry a footer
  // such as "Page 50 of 55".  When raw PIB text is available, rebuild the
  // NOTAM -> PDF page index from those markers so search results and plotted
  // hazards can always show their source page.
  function firebaseSafeNotamPageKey(id) {
    return String(id || "").toUpperCase().trim().replace(/[.#$\[\]\/]/g, "_");
  }

  function notamIdFromPageMapKey(key) {
    key = String(key || "").toUpperCase().trim();
    if (/^[A-Z]\d{3,4}\/\d{2}$/.test(key)) return key;
    var m = key.match(/^([A-Z]\d{3,4})_(\d{2})$/);
    return m ? (m[1] + "/" + m[2]) : key;
  }

  // DEV450: reuse indexes across ticker/hazard lookups instead of O(N²) rescans.
  // Dataset/array replacement and publication invalidate them. Records remain shared.
  var pibLookupCache = null;
  function invalidatePibLookupCache() { pibLookupCache = null; }
  function currentPibLookupCache() {
    var d = currentPib;
    var refs = d ? [d, d.notams, d.notams && d.notams.length, d.pageByNotam,
      d.notamPages, d.sourcePages, d.rawText, d.text, d.pibText,
      d.rawPages, d.pageTexts, d.pagesText] : [];
    if (!pibLookupCache || refs.some(function(v,i){ return v !== pibLookupCache.refs[i]; })) {
      pibLookupCache = { refs: refs, codes: null, pages: null };
    }
    return pibLookupCache;
  }
  function currentPibPageIndex() {
    var cache = currentPibLookupCache();
    return cache.pages || (cache.pages = buildCurrentPibPageIndex(currentPib));
  }

  function buildCurrentPibPageIndex(dataset) {
    var index = Object.create(null);
    if (!dataset || typeof dataset !== "object") return index;

    function remember(id, page) {
      id = String(id || "").toUpperCase().trim();
      page = parseInt(page, 10);
      if (!/^([A-Z]\d{3,4}\/\d{2})$/.test(id) || !(page > 0)) return;
      if (!index[id]) index[id] = page;
    }

    // Accept any page map/aliases already supplied by another publisher.
    var maps = [dataset.pageByNotam, dataset.notamPages, dataset.sourcePages];
    maps.forEach(function(map) {
      if (!map || typeof map !== "object") return;
      Object.keys(map).forEach(function(id) { remember(notamIdFromPageMapKey(id), map[id]); });
    });

    // Accept common per-NOTAM page field aliases.
    (Array.isArray(dataset.notams) ? dataset.notams : []).forEach(function(n) {
      if (!n) return;
      var p = n.sourcePage || n.pibPage || n.pdfPage || n.pageNumber || n.page;
      if (p) remember(n.notamId, p);
      var raw = String(n.raw || n.rawText || "");
      var pm = raw.match(/\bPage\s+(\d+)\s+of\s+\d+\b/i);
      if (pm) remember(n.notamId, pm[1]);
    });

    // Some importers retain an array containing one text string per PDF page.
    var pageArrays = [dataset.rawPages, dataset.pageTexts, dataset.pagesText];
    pageArrays.forEach(function(arr) {
      if (!Array.isArray(arr)) return;
      arr.forEach(function(pageText, i) {
        var ids = String(pageText || "").match(/\b[A-Z]\d{3,4}\/\d{2}\b/g) || [];
        ids.forEach(function(id) { remember(id, i + 1); });
      });
    });

    // Robust fallback for the full text extracted from a NATS PIB PDF.
    // The page footer occurs at the END of each page, so every NOTAM found
    // since the previous footer belongs to that footer's page number.
    var rawText = String(dataset.rawText || dataset.text || dataset.pibText || "");
    if (rawText) {
      var footerRe = /\bPage\s+(\d+)\s+of\s+(\d+)\b/gi;
      var last = 0, m;
      while ((m = footerRe.exec(rawText)) !== null) {
        var chunk = rawText.slice(last, m.index);
        var ids = chunk.match(/\b[A-Z]\d{3,4}\/\d{2}\b/g) || [];
        ids.forEach(function(id) { remember(id, m[1]); });
        last = footerRe.lastIndex;
      }
      // In case a publisher preserves page headings instead of footers,
      // also inspect explicitly delimited page chunks.
      var headingRe = /(?:^|\n)\s*<PARSED TEXT FOR PAGE:\s*(\d+)\s*\/\s*\d+>/gi;
      var starts = [], hm;
      while ((hm = headingRe.exec(rawText)) !== null) starts.push({ page: parseInt(hm[1],10), at: hm.index, body: headingRe.lastIndex });
      starts.forEach(function(s, i) {
        var end = i + 1 < starts.length ? starts[i+1].at : rawText.length;
        var ids = rawText.slice(s.body, end).match(/\b[A-Z]\d{3,4}\/\d{2}\b/g) || [];
        ids.forEach(function(id) { remember(id, s.page); });
      });
    }
    return index;
  }

  function backfillCurrentPibSourcePages(dataset) {
    invalidatePibLookupCache();
    if (!dataset || !Array.isArray(dataset.notams)) return false;
    var idx = buildCurrentPibPageIndex(dataset);
    var changed = false;
    dataset.notams.forEach(function(n) {
      if (!n || !n.notamId) return;
      var id = String(n.notamId).toUpperCase();
      var p = idx[id];
      if (p && parseInt(n.sourcePage,10) !== parseInt(p,10)) {
        n.sourcePage = parseInt(p,10);
        changed = true;
      }
    });
    if (Object.keys(idx).length) {
      var safeMap = {};
      Object.keys(idx).forEach(function(id) {
        var safeId = firebaseSafeNotamPageKey(id);
        if (safeId) safeMap[safeId] = idx[id];
      });
      dataset.pageByNotam = safeMap;
    }
    return changed;
  }

  function plottedHazardInfoForNotam(notamId) {
    var wanted = String(notamId || "").toUpperCase().trim();
    if (!wanted) return null;
    var matches = (Array.isArray(hazards) ? hazards : []).filter(function(h) {
      if (!h) return false;
      var hid = String(h.autoKey || "").toUpperCase().trim();
      if (!hid) {
        var m = String(h.notam || "").toUpperCase().match(/\b([A-Z]\d{3,4}\/\d{2})\b/);
        hid = m ? m[1] : "";
      }
      return hid === wanted;
    });
    if (!matches.length) return null;
    matches.sort(function(a,b){ return (parseInt(a.ref,10)||999) - (parseInt(b.ref,10)||999); });
    var h = matches[0];
    return { ref: hazardManualReferences(h).pin, page: hazardManualReferences(h).page, type: h.type || "", auto: !!h.autoManaged };
  }

  function currentPibSourcePage(notamId) {
    var wanted = String(notamId || "").toUpperCase().trim();
    if (!wanted || !currentPib) return null;
    var n = findPibNotamByCode(wanted);
    if (n) {
      var direct = n.sourcePage || n.pibPage || n.pdfPage || n.pageNumber || n.page;
      if (direct) return parseInt(direct, 10) || direct;
    }
    var idx = currentPibPageIndex();
    return idx[wanted] || null;
  }

  function updateHazNotamSuggestions(value) {
    var dl = document.getElementById("hazNotamCodeList");
    if (!dl) return;
    dl.innerHTML = getPibSuggestions(value)
      .map(function (n) {
        var plotted = plottedHazardInfoForNotam(n.notamId);
        var pg = currentPibSourcePage(n.notamId);
        var plotLabel = plotted ? " — plotted pin " + plotted.ref : "";
        var pageLabel = pg ? " (page " + pg + ")" : "";
        var label = n.notamId + plotLabel + pageLabel + (n.icao ? " — " + n.icao : "") + (n.eText ? " — " + n.eText.slice(0, 70) : "");
        return '<option value="' + esc(n.notamId) + '" label="' + esc(label) + '"></option>';
      })
      .join("");
  }

  function loadHazNotamFromCode(value) {
    var code = String(value || "").trim();
    if (!code) return;
    if (!currentPib || !currentPib.notams || !currentPib.notams.length) {
      setHazNotamCodeStatus("No PIB loaded. Upload today's PIB in the NOTAM tab first.", true);
      return;
    }
    var n = findPibNotamByCode(code);
    if (!n) {
      // Not a code - try it as a keyword search.
      var matches = getPibSuggestions(code);
      if (matches.length === 1) {
        n = matches[0];
      } else if (matches.length > 1) {
        setHazNotamCodeStatus(
          matches.length + " NOTAMs match “" + code + "” — pick one from the list.",
          false,
        );
        return;
      } else {
        setHazNotamCodeStatus("No NOTAM code or keyword match for “" + code + "” in current PIB.", true);
        return;
      }
    }
    document.getElementById("hazNotamCode").value = n.notamId;
    document.getElementById("hazNotam").value = pibNotamToText(n);
    applyHazardNotamText(document.getElementById("hazNotam").value, false);
    var loadedPg = currentPibSourcePage(n.notamId);
    setHazNotamCodeStatus("Loaded " + n.notamId + (loadedPg ? " — page " + loadedPg : "") + (n.icao ? " (" + n.icao + ")" : "") + " from current PIB.", false);
  }

  var hazCodeEl = document.getElementById("hazNotamCode");
  if (hazCodeEl) {
    hazCodeEl.addEventListener("input", function () {
      updateHazNotamSuggestions(this.value);
    });
    hazCodeEl.addEventListener("change", function () {
      loadHazNotamFromCode(this.value);
    });
    hazCodeEl.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        loadHazNotamFromCode(this.value);
      }
    });
  }



  /* ===== HAZDAM NOTAM / keyword insert ===== */
  var hazdamNotamPending = null;

  function hazdamNotamStatus(msg, isError) {
    var el = document.getElementById("hazdamNotamSearchStatus");
    if (!el) return;
    el.textContent = msg || "";
    el.style.color = isError ? "var(--red)" : "var(--green)";
    el.style.fontWeight = msg ? "700" : "";
  }

  function hazdamNormaliseSearchText(v) {
    return String(v || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  }

  function hazdamDangerAreaDisplay(areaId, area) {
    area = area || {};
    var display = String(area.display || areaId || "").trim();
    var name = String(area.name || area.group || "").trim();
    if (display && name && hazdamNormaliseSearchText(display) !== hazdamNormaliseSearchText(name)) return display + " " + name;
    return display || name || areaId || "Danger Area";
  }

  function hazdamAreaTokens(areaId, area) {
    area = area || {};
    var vals = [areaId, area.id, area.display, area.name, area.group].filter(Boolean);
    var out = [];
    vals.forEach(function (v) {
      var raw = String(v || "").toUpperCase().trim();
      if (!raw) return;
      out.push(raw);
      out.push(hazdamNormaliseSearchText(raw));
      var dm = raw.match(/(?:EG)?D\s*0*([0-9]{1,3}[A-Z]?)/i);
      if (dm) {
        var num = dm[1].toUpperCase();
        out.push(num);
        out.push("D" + num);
        out.push("EGD" + num);
        out.push("AREA" + num);
      }
    });
    return Array.from(new Set(out.filter(Boolean)));
  }

  function hazdamCanonicalAreaRef(v) {
    var raw = String(v || "").toUpperCase().replace(/\s+/g, "");
    var m = raw.match(/(?:EG)?D0*([0-9]{1,3}[A-Z]?)/);
    if (!m) return "";
    var num = m[1].toUpperCase();
    // Keep normal UK DA display format, e.g. 117 -> EGD117, 011B -> EGD011B.
    var n = num.match(/^(\d+)([A-Z]?)$/);
    if (!n) return "EGD" + num;
    return "EGD" + String(parseInt(n[1], 10)).padStart(3, "0") + (n[2] || "");
  }

  function hazdamExtractAreaRefsFromNotam(n) {
    var eText = String((n && n.eText) || "").toUpperCase();
    var raw = String((n && n.raw) || "").toUpperCase();
    var text = (eText + " " + raw).trim();
    var refs = [];
    function add(v){
      var c = hazdamCanonicalAreaRef(v);
      if (c && refs.indexOf(c) === -1) refs.push(c);
    }

    // Release235: first take the explicit designator immediately following
    // "DANGER AREA".  This is the strongest possible match and specifically
    // covers E)DANGER AREA EGD129 WESTON-ON-THE-GREEN ACTIVATED.
    var explicit = eText.match(/\bDANGER\s+AREA(?:S)?\s+(?:EG\s*)?D\s*0*([0-9]{1,3}[A-Z]?)\b/);
    if (explicit) add("EGD" + explicit[1]);

    // Then collect any additional DA designators in the whole NOTAM.
    var re = /\b(?:EG\s*)?D\s*0*([0-9]{1,3}[A-Z]?)\b/g;
    var m;
    while ((m = re.exec(text)) !== null) add("EGD" + m[1]);
    return refs;
  }

  function hazdamFindAreaByCanonicalRef(ref) {
    var wanted = hazdamCanonicalAreaRef(ref);
    if (!wanted) return null;

    // Release235: search both runtime HAZDAM architecture and the master
    // FISO_DATA architecture.  Earlier code used `A || B`, so if HAZDAM
    // existed but did not yet contain a newly-added area such as EGD129,
    // matching stopped before FISO_DATA was ever checked.
    var sources = [];
    if (window.HAZDAM && window.HAZDAM.staticAreas) sources.push(window.HAZDAM.staticAreas);
    if (window.FISO_DATA && window.FISO_DATA.dangerAreas) sources.push(window.FISO_DATA.dangerAreas);

    var seen = Object.create(null);
    for (var sidx = 0; sidx < sources.length; sidx++) {
      var areas = sources[sidx] || {};
      var keys = Object.keys(areas);
      for (var i = 0; i < keys.length; i++) {
        var id = keys[i];
        if (seen[id]) continue;
        seen[id] = true;
        var area = areas[id] || {};
        var candidates = [id, area.id, area.display, area.name, area.group];
        for (var j = 0; j < candidates.length; j++) {
          if (hazdamCanonicalAreaRef(candidates[j]) === wanted) return { id: id, area: area };
        }
      }
    }
    return null;
  }

  // Release267: classify Danger Area NOTAMs as ACTIVATE or DEACTIVATE.
  // DEACTIVATED is no longer discarded: it temporarily supersedes the ENR
  // schedule for the promulgated NOTAM window, after which ENR resumes.
  function hazdamDangerNotamAction(n) {
    if (!n) return "";
    var text = [n.eText, n.raw, n.rawText, n.notamText]
      .map(function(v){ return String(v || ""); }).join(" ")
      .toUpperCase().replace(/\s+/g, " ");
    if (!/\bDANGER\s+AREA(?:S)?\b/.test(text)) return "";
    if (/\bDEACTIVATED\b/.test(text)) return "deactivate";
    var q = String(n.qLine || "").toUpperCase();
    if (/\bACTIV(?:E|ATED|ATION)\b/.test(text) || /\bACTIVAT(?:E|ED|ION)\b/.test(text) || /\/QRD[A-Z]{2}\//.test(q) || /\/QRDCA\//.test(q)) return "activate";
    return "";
  }

  function hazdamNotamIsDeactivation(n) {
    return hazdamDangerNotamAction(n) === "deactivate";
  }

  function hazdamFindProgrammedAreaForNotam(n, query) {
    // Deterministic matching: never match loose numeric fragments from Q-line coordinates.
    // 1) Use the explicit DA designator in the NOTAM E)/raw text, e.g. EGD011B.
    var refs = hazdamExtractAreaRefsFromNotam(n);
    for (var r = 0; r < refs.length; r++) {
      var direct = hazdamFindAreaByCanonicalRef(refs[r]);
      if (direct) return direct;
    }
    // 2) If the user typed a DA designator directly, use that exact designator.
    var qRef = hazdamCanonicalAreaRef(query);
    if (qRef) {
      var qArea = hazdamFindAreaByCanonicalRef(qRef);
      if (qArea) return qArea;
    }
    // 3) Area-name fallback only against E)/raw words and programmed names, not Q-line coordinate digits.
    var areas = (window.HAZDAM && window.HAZDAM.staticAreas) || (window.FISO_DATA && window.FISO_DATA.dangerAreas) || {};
    var eText = hazdamNormaliseSearchText([n && n.eText, n && n.raw].join(" "));
    var best = null;
    Object.keys(areas).some(function (id) {
      var area = areas[id] || {};
      var names = [area.name, area.group].filter(Boolean).map(hazdamNormaliseSearchText).filter(function(x){ return x && x.length >= 4; });
      var ok = names.some(function(name){ return eText.indexOf(name) !== -1; });
      if (ok) best = { id: id, area: area };
      return ok;
    });
    return best;
  }

  function hazdamNotamMatchesQuery(n, query) {
    var q = String(query || "").trim();
    if (!q || !n) return false;
    var nq = hazdamNormaliseSearchText(q);
    var hay = hazdamNormaliseSearchText([n.notamId, n.qLine, n.a, n.b, n.c, n.d, n.eText, n.f, n.g, n.raw].join(" "));
    if (nq && hay.indexOf(nq) !== -1) return true;
    return q.toLowerCase().split(/\s+/).filter(Boolean).every(function (w) {
      return String([n.notamId, n.qLine, n.a, n.b, n.c, n.d, n.eText, n.f, n.g, n.raw].join(" ")).toLowerCase().indexOf(w) !== -1;
    });
  }

  function getHazdamPibMatches(query, limit) {
    limit = limit || 20;
    if (!currentPib || !Array.isArray(currentPib.notams)) return [];
    var q = String(query || "").trim();
    var qNorm = hazdamNormaliseSearchText(q);
    var qArea = hazdamCanonicalAreaRef(q);
    var seen = Object.create(null);
    var out = [];
    function push(n, priority) {
      if (!n || !n.notamId || seen[n.notamId]) return;
      var am = hazdamFindProgrammedAreaForNotam(n, q);
      if (!am) return;
      seen[n.notamId] = true;
      out.push({ notam: n, areaMatch: am, label: hazdamDangerAreaDisplay(am.id, am.area), priority: priority || 9 });
    }

    // Priority 1: exact NOTAM code, e.g. D2696 or D2696/26, must win.
    var exact = findPibNotamByCode(q);
    if (exact) push(exact, 0);

    // Priority 2: explicit DA designator/name hits in the active PIB.
    currentPib.notams.forEach(function (n) {
      if (out.length >= limit) return;
      var refs = hazdamExtractAreaRefsFromNotam(n);
      var refHit = qArea && refs.indexOf(qArea) !== -1;
      var areaMatch = hazdamFindProgrammedAreaForNotam(n, q);
      var label = areaMatch ? hazdamNormaliseSearchText(hazdamDangerAreaDisplay(areaMatch.id, areaMatch.area) + " " + areaMatch.id) : "";
      var nameHit = qNorm && qNorm.length >= 3 && label.indexOf(qNorm) !== -1;
      if (refHit || nameHit) push(n, 1);
    });

    // Priority 3: normal NOTAM suggestions / keyword search.
    getPibSuggestions(q).forEach(function(n){ push(n, 2); });
    currentPib.notams.forEach(function (n) {
      if (out.length >= limit) return;
      if (hazdamNotamMatchesQuery(n, q)) push(n, 3);
    });

    out.sort(function (a, b) {
      return (a.priority - b.priority) || String(a.notam.notamId).localeCompare(String(b.notam.notamId));
    });
    return out.slice(0, limit);
  }

  function hazdamFormatLevel(raw, fallback) {
    var v = String(raw || "").trim().toUpperCase();
    if (!v) return fallback || "";
    v = v.replace(/\s+/g, " ").trim();
    // NOTAM F)/G) fields commonly include suffixes such as AMSL or ALT, e.g. "4500FT AMSL".
    // HAZDAM edit validation expects a clean operational level, so normalise before saving.
    v = v.replace(/\b(AMSL|ALT|AGL)\b/g, "").replace(/\s+/g, " ").trim();
    if (v === "000") return "SFC";
    if (v === "999") return "UNL";
    if (/^FL\s*\d{1,3}$/.test(v)) return v.replace(/\s+/g, "");
    if (/^\d{3}$/.test(v)) return "FL" + v;
    var ft = v.match(/^(\d{1,5})\s*(?:FT)?$/);
    if (ft) return ft[1] + "FT";
    return v;
  }

  function hazdamBcdDateToUtcParts(v) {
    var m = String(v || "").match(/^(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/);
    if (!m) return null;
    return { year: 2000 + parseInt(m[1], 10), month: parseInt(m[2], 10) - 1, day: parseInt(m[3], 10), hh: parseInt(m[4], 10), mm: parseInt(m[5], 10) };
  }

  // Release231: calculate civil sunrise/sunset in UTC for NOTAM D-field
  // constructs such as SR-SS and SS-SR. The Q-line centre is sufficiently
  // precise for scheduling; B/C remains the hard validity envelope.
  function hazdamSolarUtcMinutes(date, lat, lon, sunrise) {
    function rad(x){ return x*Math.PI/180; }
    function deg(x){ return x*180/Math.PI; }
    function norm(x,m){ return ((x%m)+m)%m; }
    var y=date.getUTCFullYear(), mo=date.getUTCMonth(), da=date.getUTCDate();
    var n=Math.floor((Date.UTC(y,mo,da)-Date.UTC(y,0,0))/86400000);
    var lngHour=lon/15, t=n+((sunrise?6:18)-lngHour)/24;
    var M=0.9856*t-3.289;
    var L=norm(M+1.916*Math.sin(rad(M))+0.020*Math.sin(rad(2*M))+282.634,360);
    var RA=norm(deg(Math.atan(0.91764*Math.tan(rad(L)))),360);
    var Lq=Math.floor(L/90)*90, RAq=Math.floor(RA/90)*90; RA=(RA+(Lq-RAq))/15;
    var sinDec=0.39782*Math.sin(rad(L)), cosDec=Math.cos(Math.asin(sinDec));
    var cosH=(Math.cos(rad(90.833))-sinDec*Math.sin(rad(lat)))/(cosDec*Math.cos(rad(lat)));
    if(cosH>1||cosH<-1)return null;
    var H=sunrise ? 360-deg(Math.acos(cosH)) : deg(Math.acos(cosH)); H/=15;
    var T=H+RA-0.06571*t-6.622;
    var UT=norm(T-lngHour,24);
    return Math.round(UT*60)%1440;
  }
  function hazdamQLineLatLon(n){
    var q=String(n&&n.qLine||"").toUpperCase();
    var m=q.match(/\/(\d{2})(\d{2})([NS])(\d{3})(\d{2})([EW])\d{3}(?:\s|$|\/)/);
    if(!m)return null;
    var lat=Number(m[1])+Number(m[2])/60, lon=Number(m[4])+Number(m[5])/60;
    if(m[3]==="S")lat=-lat; if(m[6]==="W")lon=-lon;
    return {lat:lat,lon:lon};
  }
  function hazdamMinutesHHMM(v){ v=(v+1440)%1440; return pad(Math.floor(v/60))+":"+pad(v%60); }

  function hazdamPibNotamTodayTimes(n) {
    var now = new Date();
    var dd = pad(now.getUTCDate());
    var d = String((n && n.d) || "").toUpperCase().replace(/[\u2010\u2011\u2012\u2013\u2014\u2212]/g, "-").replace(/\s+/g, " ").trim();
    var solar=d.match(/\b(SR|SS)\s*-\s*(SR|SS)\b/);
    if(solar){
      var pos=null;
      var refs=hazdamExtractAreaRefsFromNotam(n);
      if(refs.length){
        var areaHit=hazdamFindAreaByCanonicalRef(refs[0]);
        var st=areaHit && areaHit.area;
        if(st && Array.isArray(st.circleCenter) && st.circleCenter.length>=2){
          pos={lat:Number(st.circleCenter[0]),lon:Number(st.circleCenter[1])};
        } else if(st && Array.isArray(st.labelLatLng) && st.labelLatLng.length>=2){
          pos={lat:Number(st.labelLatLng[0]),lon:Number(st.labelLatLng[1])};
        }
      }
      if(!pos) pos=hazdamQLineLatLon(n);
      if(pos){
        var start=hazdamSolarUtcMinutes(now,pos.lat,pos.lon,solar[1]==="SR");
        var finishDate=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+(solar[1]==="SS"&&solar[2]==="SR"?1:0)));
        var end=hazdamSolarUtcMinutes(finishDate,pos.lat,pos.lon,solar[2]==="SR");
        if(start!==null&&end!==null)return {startUTC:hazdamMinutesHHMM(start),endUTC:hazdamMinutesHHMM(end),source:"D "+solar[0]};
      }
    }
    var ranges = [];
    if (d) {
      var dayRe = new RegExp("(?:^|[,; ]+)(" + dd + ")\\s+((?:\\d{4}-\\d{4})(?:\\s+\\d{4}-\\d{4})*)", "g");
      var m;
      while ((m = dayRe.exec(d)) !== null) {
        var sub = m[2].match(/\d{4}-\d{4}/g) || [];
        ranges = ranges.concat(sub);
      }
      if (!ranges.length && /\d{4}-\d{4}/.test(d) && !/(?:^|[,; ]+)\d{2}\s+\d{4}-\d{4}/.test(d)) {
        ranges = d.match(/\d{4}-\d{4}/g) || [];
      }
    }
    if (ranges.length) {
      var first = ranges[0].slice(0, 4);
      var last = ranges[ranges.length - 1].slice(5, 9);
      return { startUTC: first.slice(0, 2) + ":" + first.slice(2), endUTC: last.slice(0, 2) + ":" + last.slice(2), source: "D" };
    }
    var b = hazdamBcdDateToUtcParts(n && n.b);
    var c = hazdamBcdDateToUtcParts(n && n.c);
    if (b && c) {
      var todayStart = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0);
      var todayEnd = todayStart + 86400000;
      var bMs = Date.UTC(b.year, b.month, b.day, b.hh, b.mm);
      var cMs = Date.UTC(c.year, c.month, c.day, c.hh, c.mm);
      if (cMs > todayStart && bMs < todayEnd) {
        var st = new Date(Math.max(bMs, todayStart));
        var en = new Date(Math.min(cMs, todayEnd));
        return { startUTC: pad(st.getUTCHours()) + ":" + pad(st.getUTCMinutes()), endUTC: pad(en.getUTCHours()) + ":" + pad(en.getUTCMinutes()), source: "B/C" };
      }
    }
    return { startUTC: "", endUTC: "", source: "" };
  }

  function hazdamPayloadFromPibNotam(n, areaMatch) {
    var qLower = n && n.lower;
    var qUpper = n && n.upper;
    var lower = hazdamFormatLevel((n && n.f) || qLower, areaMatch && areaMatch.area && areaMatch.area.lower || "SFC");
    var upper = hazdamFormatLevel((n && n.g) || qUpper, areaMatch && areaMatch.area && areaMatch.area.upper || "UNL");
    var times = hazdamPibNotamTodayTimes(n);
    return {
      notamId: n.notamId,
      sourcePage: n.sourcePage || currentPibSourcePage(n.notamId) || null,
      lower: lower,
      upper: upper,
      startUTC: times.startUTC,
      endUTC: times.endUTC,
      b: String(n.b || ""),
      c: String(n.c || ""),
      d: String(n.d || ""),
      notamText: pibNotamToText(n),
      source: "NOTAM " + n.notamId,
      notes: "Inserted from PIB NOTAM " + n.notamId + "." + (n.eText ? " " + String(n.eText).slice(0, 220) : ""),
      updatedBy: "ADMIN"
    };
  }

  function hazdamResolveNotamSearch(value, quiet) {
    var q = String(value || "").trim();
    hazdamNotamPending = null;
    if (!q) {
      if (!quiet) hazdamNotamStatus("Enter a NOTAM code, danger area number, or keyword.", true);
      return null;
    }
    if (!currentPib || !Array.isArray(currentPib.notams) || !currentPib.notams.length) {
      hazdamNotamStatus("No PIB loaded. Upload today's PIB first.", true);
      return null;
    }
    var matches = getHazdamPibMatches(q, 20);
    if (!matches.length) {
      // There may be a NOTAM match, but not one linked to a programmed FFApp DA.
      var anyNotam = findPibNotamByCode(q) || getPibSuggestions(q)[0] || null;
      if (anyNotam || currentPib.notams.some(function(n){ return hazdamNotamMatchesQuery(n, q); })) {
        hazdamNotamStatus("No danger area programmed into FFApp, contact Simon Vaughan for advice.", true);
      } else {
        hazdamNotamStatus("No NOTAM code, danger area number, or keyword match for “" + q + "” in current PIB.", true);
      }
      return null;
    }
    var chosen = matches[0].notam;
    var areaMatch = matches[0].areaMatch;
    var payload = hazdamPayloadFromPibNotam(chosen, areaMatch);
    hazdamNotamPending = { notam: chosen, areaId: areaMatch.id, area: areaMatch.area, payload: payload };
    var display = hazdamDangerAreaDisplay(areaMatch.id, areaMatch.area);
    hazdamNotamStatus(
      "Ready: " + display + " — " + chosen.notamId + " — " +
        (payload.startUTC && payload.endUTC ? payload.startUTC + "-" + payload.endUTC + " UTC" : "B/C valid today") +
        " — " + payload.lower + " to " + payload.upper + ". Press Insert NOTAM Danger Area.",
      false
    );
    return hazdamNotamPending;
  }

  function updateHazdamNotamSuggestions(value) {
    var dl = document.getElementById("hazdamNotamSearchList");
    if (!dl) return;
    dl.innerHTML = getHazdamPibMatches(value, 20).map(function (hit) {
      var n = hit.notam;
      var da = hit.label;
      var payload = hazdamPayloadFromPibNotam(n, hit.areaMatch);
      var label = n.notamId + " — " + da + " — " +
        ((payload.startUTC && payload.endUTC) ? (payload.startUTC + "-" + payload.endUTC + " UTC") : "B/C valid today") +
        " — " + payload.lower + " to " + payload.upper;
      return '<option value="' + esc(n.notamId) + '" label="' + esc(label) + '"></option>';
    }).join("");
  }

  function wireHazdamNotamSearch() {
    var input = document.getElementById("hazdamNotamSearch");
    var btn = document.getElementById("hazdamInsertNotamBtn");
    if (!input || !btn || input.__ffappWired) return;
    input.__ffappWired = true;
    input.addEventListener("input", function () { updateHazdamNotamSuggestions(this.value); });
    input.addEventListener("change", function () { hazdamResolveNotamSearch(this.value, false); });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") { e.preventDefault(); hazdamResolveNotamSearch(this.value, false); }
    });
    btn.addEventListener("click", function () {
      var pending = hazdamNotamPending || hazdamResolveNotamSearch(input.value, false);
      if (!pending) return;
      if (!window.HAZDAM || typeof window.HAZDAM.applyNotamToArea !== "function") {
        hazdamNotamStatus("HAZDAM is still loading. Try again in a moment.", true);
        return;
      }
      try {
        window.HAZDAM.applyNotamToArea(pending.areaId, pending.payload);
        if (window.HAZDAM.setVisible) window.HAZDAM.setVisible(true);
        var display = hazdamDangerAreaDisplay(pending.areaId, pending.area);
        hazdamNotamStatus("Inserted " + pending.notam.notamId + " into " + display + " and plotted the danger area on the map.", false);
      } catch (err) {
        hazdamNotamStatus("Unable to insert NOTAM Danger Area: " + (err && err.message ? err.message : err), true);
      }
    });
  }
  setTimeout(wireHazdamNotamSearch, 500);
  setTimeout(wireHazdamNotamSearch, 1500);

  /* ===== Multi-point NOTAM plotting ===== */
  var hazMultiMode = false;
  var HAZ_PT_BLOCK = 6; // rows are added in blocks of 6

  function hazPtRowHtml(i) {
    return (
      '<div class="haz-pt-row" data-idx="' + i + '">' +
      '<span class="idx">' + (i + 1) + "</span>" +
      '<input type="text" class="hazPtLat" placeholder="N52&#176;38&#39;25&quot;" autocomplete="off">' +
      '<input type="text" class="hazPtLon" placeholder="W001&#176;44&#39;12&quot;" autocomplete="off">' +
      '<input type="checkbox" class="hazPtPlot" checked title="Include this point in the polygon">' +
      "</div>"
    );
  }

  function hazPtRows() {
    var wrap = document.getElementById("hazPointsRows");
    return wrap ? Array.prototype.slice.call(wrap.querySelectorAll(".haz-pt-row")) : [];
  }

  // Ensure at least `n` rows exist, always in multiples of HAZ_PT_BLOCK.
  function ensureHazPtRows(n) {
    var wrap = document.getElementById("hazPointsRows");
    if (!wrap) return;
    var want = Math.max(HAZ_PT_BLOCK, Math.ceil(n / HAZ_PT_BLOCK) * HAZ_PT_BLOCK);
    var have = hazPtRows().length;
    for (var i = have; i < want; i++) wrap.insertAdjacentHTML("beforeend", hazPtRowHtml(i));
  }

  // Auto-grow: when any field in the last block gains content, add 6 more rows.
  (function () {
    var wrap = document.getElementById("hazPointsRows");
    if (!wrap) return;
    wrap.addEventListener("input", function (e) {
      var row = e.target && e.target.closest ? e.target.closest(".haz-pt-row") : null;
      if (!row) return;
      var rows = hazPtRows();
      var idx = rows.indexOf(row);
      if (idx >= rows.length - 1 && (e.target.value || "").trim() !== "")
        ensureHazPtRows(rows.length + 1);
    });
  })();

  function clearHazPtRows() {
    var wrap = document.getElementById("hazPointsRows");
    if (!wrap) return;
    wrap.innerHTML = "";
    ensureHazPtRows(HAZ_PT_BLOCK);
  }

  // Fill rows from a list of {lat, lon}; replaces current contents.
  function fillHazPtRows(points) {
    var wrap = document.getElementById("hazPointsRows");
    if (!wrap) return;
    wrap.innerHTML = "";
    ensureHazPtRows(points.length);
    var rows = hazPtRows();
    points.forEach(function (p, i) {
      if (!rows[i]) return;
      rows[i].querySelector(".hazPtLat").value = decToDDM(p.lat, true);
      rows[i].querySelector(".hazPtLon").value = decToDDM(p.lon, false);
    });
  }

  // Drop a picked/shortcut coordinate into the first empty row.
  function hazFillNextEmptyRow(lat, lon) {
    ensureHazPtRows(HAZ_PT_BLOCK);
    var rows = hazPtRows();
    for (var i = 0; i < rows.length; i++) {
      var latEl = rows[i].querySelector(".hazPtLat");
      var lonEl = rows[i].querySelector(".hazPtLon");
      if (!latEl.value.trim() && !lonEl.value.trim()) {
        latEl.value = decToDDM(lat, true);
        lonEl.value = decToDDM(lon, false);
        if (i >= rows.length - 1) ensureHazPtRows(rows.length + 1);
        return;
      }
    }
  }

  // Every coordinate in a NOTAM text: DDMM(SS)N/S DDDMM(SS)E/W.
  // For polygon NOTAMs, prefer the E) narrative text and ignore the Q) centre/radius
  // coordinate. Including the Q) coordinate can make multi-leg areas look like a
  // spider/star because the first leg starts at the NOTAM centre instead of the
  // first boundary vertex.
  function parseNotamAllCoords(text) {
    var raw = String(text || "");
    var source = raw;
    var eMatch = raw.match(/E\)([\s\S]*?)(?:\n\s*F\)|\r\n\s*F\)|F\))/i);
    if (eMatch && eMatch[1]) source = eMatch[1];
    else source = raw.replace(/^\s*Q\)[^\n\r]*/im, "");

    var re = /(\d{2})(\d{2})(\d{2})?\s?([NS])\s?(\d{3})(\d{2})(\d{2})?\s?([EW])/g;
    var out = [];
    var m;
    while ((m = re.exec(source)) && out.length < 60) {
      var lat = +m[1] + +m[2] / 60 + (m[3] ? +m[3] / 3600 : 0);
      if (m[4] === "S") lat = -lat;
      var lon = +m[5] + +m[6] / 60 + (m[7] ? +m[7] / 3600 : 0);
      if (m[8] === "W") lon = -lon;
      if (lat > 90 || lon > 180) continue;
      out.push({ lat: lat, lon: lon });
    }

    // Many NOTAMs repeat the first point at the end to close the polygon. Leaflet
    // closes polygons automatically, so remove the duplicate closing point only.
    if (out.length > 2) {
      var first = out[0], last = out[out.length - 1];
      if (Math.abs(first.lat - last.lat) < 0.00001 && Math.abs(first.lon - last.lon) < 0.00001) out.pop();
    }
    return out;
  }

  function setHazMode(multi) {
    hazMultiMode = !!multi;
    var t = document.getElementById("hazModeToggle");
    if (t) t.setAttribute("aria-pressed", hazMultiMode ? "true" : "false");
    var s = document.getElementById("hazModeSingleLbl");
    var mLbl = document.getElementById("hazModeMultiLbl");
    if (s) s.classList.toggle("active", !hazMultiMode);
    if (mLbl) mLbl.classList.toggle("active", hazMultiMode);
    var singleRow = document.getElementById("hazSingleLatLonRow");
    if (singleRow) singleRow.style.display = hazMultiMode ? "none" : "";
    var multiWrap = document.getElementById("hazMultiWrap");
    if (multiWrap) multiWrap.style.display = hazMultiMode ? "" : "none";
    if (hazMultiMode) {
      ensureHazPtRows(HAZ_PT_BLOCK);
      // Re-run autofill over whatever NOTAM text is already pasted.
      var txt = document.getElementById("hazNotam").value;
      if (txt.trim()) {
        var pts = parseNotamAllCoords(txt);
        if (pts.length) fillHazPtRows(pts);
      }
    }
  }

  (function () {
    var t = document.getElementById("hazModeToggle");
    if (t)
      t.addEventListener("click", function () {
        setHazMode(!hazMultiMode);
      });
  })();

  (function () {
    var typeEl = document.getElementById("hazType");
    var refEl = document.getElementById("hazRef");
    if (typeEl) typeEl.addEventListener("change", function () {
      if (!hazEditing) updateHazNextRef(true);
      updateHazRadiusUI();
      updateHazPickPreview();
    });
    var radiusEl = document.getElementById("hazRadiusNm");
    if (radiusEl) radiusEl.addEventListener("change", function () { updateHazPickPreviewCircle(); });
    if (refEl) refEl.addEventListener("focus", function () { if (!refEl.value) updateHazNextRef(true); });
    ["hazLat", "hazLon", "hazCoord", "hazLower", "hazUpper", "hazStart", "hazFinish", "hazNotam", "hazNotamCode", "hazRef"].forEach(function (id) {
      var el = document.getElementById(id);
      if (!el) return;
      ["input", "change"].forEach(function (evt) {
        el.addEventListener(evt, function () { setTimeout(updateHazSaveButtonState, 0); });
      });
    });
    document.addEventListener("input", function (e) {
      if (e.target && (e.target.classList.contains("hazPtLat") || e.target.classList.contains("hazPtLon") || e.target.classList.contains("hazPtPlot"))) {
        setTimeout(updateHazSaveButtonState, 0);
      }
    });
    updateHazNextRef(true);
    updateHazRadiusUI();
    setTimeout(updateHazSaveButtonState, 0);
  })();

  function readOptionalHazardTimes(type) {
    var radiusOnly = isAlwaysVisibleRadiusHazardType(type);
    if (radiusOnly) return { ok: true, startISO: "", finishISO: "", alwaysActive: true };
    var startEl = document.getElementById("hazStart");
    var finishEl = document.getElementById("hazFinish");
    var startValue = ((startEl && startEl.value) || "").trim();
    var finishValue = ((finishEl && finishEl.value) || "").trim();
    if (!startValue && !finishValue) {
      return { ok: true, startISO: "", finishISO: "", alwaysActive: true };
    }
    if (!startValue || !finishValue) {
      alert("Enter both Start and Finish times, or leave both blank.");
      return { ok: false };
    }
    var startMs = parseUtcTimeOnly(startValue);
    var finishMs = parseUtcTimeOnly(finishValue);
    if (isNaN(startMs) || isNaN(finishMs)) {
      alert("Enter valid Start and Finish times, or leave both blank.");
      return { ok: false };
    }
    if (finishMs <= startMs) {
      alert("Finish time must be after the start time.");
      return { ok: false };
    }
    return {
      ok: true,
      startISO: new Date(startMs).toISOString(),
      finishISO: new Date(finishMs).toISOString(),
      alwaysActive: false
    };
  }

  function updateHazSaveButtonState() {
    var btn = document.getElementById("hazAdd");
    if (!btn) return;
    var hasPosition = false;
    if (hazMultiMode) {
      hasPosition = hazPtRows().some(function (row) {
        if (!row.querySelector(".hazPtPlot").checked) return false;
        return !isNaN(parseDMSHaz(row.querySelector(".hazPtLat").value.trim())) &&
          !isNaN(parseDMSHaz(row.querySelector(".hazPtLon").value.trim()));
      });
    } else {
      hasPosition = !isNaN(parseDMSHaz(document.getElementById("hazLat").value)) &&
        !isNaN(parseDMSHaz(document.getElementById("hazLon").value));
    }
    var ready = !!hazEditing || hasPosition;
    btn.disabled = !ready;
    btn.classList.toggle("haz-save-ready", ready);
    if (hazEditing) {
      btn.textContent = "SAVE CHANGES";
    } else {
      btn.textContent = ready ? "Save hazard" : (pickingHazard ? "Pick position on map" : "Add hazard");
    }
  }

  // Multi-point "Add hazard pin": one hazard per ticked row, sharing the
  // activity/ref/limits/NOTAM; per-point time (if set) overrides Start.
  function hazAddMultiPoints() {
    var type = document.getElementById("hazType").value;
    var ref = parseInt(document.getElementById("hazRef").value, 10);
    var radiusOnly = isAlwaysVisibleRadiusHazardType(type);
    var lower = radiusOnly ? "" : document.getElementById("hazLower").value.trim();
    var upper = radiusOnly ? "" : document.getElementById("hazUpper").value.trim();
    var timeData = readOptionalHazardTimes(type);
    if (!timeData.ok) return;
    var notamTxt = document.getElementById("hazNotam").value.trim();

    if (isNaN(ref) || ref < 1 || ref > 99) {
      alert("Ref # must be between 1 and 99.");
      return;
    }
    var points = [];
    var badRow = null;
    hazPtRows().forEach(function (row, i) {
      var latStr = row.querySelector(".hazPtLat").value.trim();
      var lonStr = row.querySelector(".hazPtLon").value.trim();
      if (!latStr && !lonStr) return; // empty row
      var lat = parseDMSHaz(latStr);
      var lon = parseDMSHaz(lonStr);
      if (isNaN(lat) || isNaN(lon)) {
        if (badRow === null) badRow = i + 1;
        return;
      }
      if (!row.querySelector(".hazPtPlot").checked) return;
      points.push({ lat: lat, lon: lon });
    });

    if (badRow !== null) {
      alert("Point " + badRow + " has an invalid latitude/longitude (include N/S and E/W).");
      return;
    }
    if (!points.length) {
      alert("No plottable points. Fill in at least one LAT/LON row (or select a NOTAM to auto-fill them).");
      return;
    }

    // One hazard: the points form a polygon, the numbered pin sits at
    // its centre.
    var cLat = 0,
      cLon = 0;
    points.forEach(function (p) {
      cLat += p.lat;
      cLon += p.lon;
    });
    cLat /= points.length;
    cLon /= points.length;

    var newHazard = {
      id: uid(),
      type: type,
      ref: ref,
      lat: cLat,
      lon: cLon,
      points: points.length > 1 ? points : undefined,
      lower: lower,
      upper: upper,
      startISO: timeData.startISO,
      finishISO: timeData.finishISO,
      alwaysActive: timeData.alwaysActive,
      notam: notamTxt,
      scheduleD: (function(){ var d = parseNotamForHazard(notamTxt); return d.scheduleD || ""; })(),
      validStartISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validStartISO || ""; })(),
      validFinishISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validFinishISO || ""; })(),
      radiusNm: isRadiusHazardType(type) ? readHazRadiusNm() : (function () {
        var d = parseNotamForHazard(notamTxt);
        return d.radiusNm;
      })(),
    };
    if (hazEditing) {
      var editingId = hazEditing;
      var existingHazard = findHazardById(editingId);
      if (!existingHazard) {
        alert("The selected hazard could not be found. No changes were saved.");
        return;
      }
      newHazard.id = editingId;
      // Editing must retain the reference of the selected object.
      newHazard.ref = existingHazard.ref;
      hazards = hazards.map(function (x) { return String(x.id) === String(editingId) ? newHazard : x; });
      hazEditing = null;
      hazEditingOriginal = null;
      clearHazardEditBoxHighlight();
      document.getElementById("hazAdd").textContent = "Add hazard";
    } else {
      hazards.push(newHazard);
    }

    saveJSON(LS_KEY_HAZARDS, hazards);
    renderHazards();
    focusAddedHazard(newHazard);
    clearHazPickPreview();
    resetHazardPickingMode();
    clearHazPtRows();
    ["hazCoord", "hazRef", "hazLower", "hazUpper", "hazStart", "hazFinish", "hazNotamCode", "hazNotam"].forEach(
      function (id) {
        document.getElementById(id).value = "";
      },
    );
    updateHazNextRef(true);
    var completedMultiSaveBtn = document.getElementById("hazAdd");
    if (completedMultiSaveBtn) {
      completedMultiSaveBtn.disabled = true;
      completedMultiSaveBtn.textContent = "Add hazard";
      completedMultiSaveBtn.classList.remove("haz-save-ready");
    }
    updateHazSaveButtonState();
  }

  document.getElementById("hazAdd").addEventListener("click", function () {
    if (hazMultiMode) {
      hazAddMultiPoints();
      return;
    }
    var type = document.getElementById("hazType").value;
    var ref = parseInt(document.getElementById("hazRef").value, 10);
    var lat = parseDMSHaz(document.getElementById("hazLat").value);
    var lon = parseDMSHaz(document.getElementById("hazLon").value);
    var radiusOnly = isAlwaysVisibleRadiusHazardType(type);
    var lower = radiusOnly ? "" : document.getElementById("hazLower").value.trim();
    var upper = radiusOnly ? "" : document.getElementById("hazUpper").value.trim();
    var timeData = readOptionalHazardTimes(type);
    if (!timeData.ok) return;
    var notamTxt = document.getElementById("hazNotam").value.trim();

    if (isNaN(lat) || isNaN(lon)) {
      alert(
        "Latitude and longitude are required (or use the PIB coordinate shortcut).",
      );
      return;
    }
    if (isNaN(ref) || ref < 1 || ref > 99) {
      alert("Ref # must be between 1 and 99.");
      return;
    }
    if (hazEditing) {
      var editingId = hazEditing;
      var existingHazard = findHazardById(editingId);
      if (!existingHazard) {
        alert("The selected hazard could not be found. No changes were saved.");
        return;
      }
      var updatedHazard = {
        id: existingHazard.id,
        type: type,
        // The selected hazard keeps its Activity Ref throughout editing.
        ref: existingHazard.ref,
        lat: lat,
        lon: lon,
        lower: lower,
        upper: upper,
        startISO: timeData.startISO,
        finishISO: timeData.finishISO,
        alwaysActive: timeData.alwaysActive,
        notam: notamTxt,
        scheduleD: (function(){ var d = parseNotamForHazard(notamTxt); return d.scheduleD || ""; })(),
        validStartISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validStartISO || ""; })(),
        validFinishISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validFinishISO || ""; })(),
        radiusNm: isRadiusHazardType(type) ? readHazRadiusNm() : (function(){ var d = parseNotamForHazard(notamTxt); return d.radiusNm; })(),
      };
      hazards = hazards.map(function (x) { return String(x.id) === String(editingId) ? updatedHazard : x; });
      hazEditing = null;
      hazEditingOriginal = null;
      clearHazardEditBoxHighlight();
      document.getElementById("hazAdd").textContent = "Add hazard";
    } else {
      var newHazard = {
        id: uid(),
        type: type,
        ref: ref,
        lat: lat,
        lon: lon,
        lower: lower,
        upper: upper,
        startISO: timeData.startISO,
        finishISO: timeData.finishISO,
        alwaysActive: timeData.alwaysActive,
        notam: notamTxt,
        scheduleD: (function(){ var d = parseNotamForHazard(notamTxt); return d.scheduleD || ""; })(),
        validStartISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validStartISO || ""; })(),
        validFinishISO: (function(){ var d = parseNotamForHazard(notamTxt); return d.validFinishISO || ""; })(),
        radiusNm: isRadiusHazardType(type) ? readHazRadiusNm() : (function(){ var d = parseNotamForHazard(notamTxt); return d.radiusNm; })(),
      };
      hazards.push(newHazard);
    }
    saveJSON(LS_KEY_HAZARDS, hazards);
    renderHazards();
    if (typeof newHazard !== "undefined") focusAddedHazard(newHazard);
    clearHazPickPreview();
    resetHazardPickingMode();
    var completedSaveBtn = document.getElementById("hazAdd");
    if (completedSaveBtn) {
      completedSaveBtn.disabled = true;
      completedSaveBtn.textContent = "Add hazard";
      completedSaveBtn.classList.remove("haz-save-ready");
    }
    [
      "hazCoord",
      "hazRef",
      "hazLat",
      "hazLon",
      "hazLower",
      "hazUpper",
      "hazStart",
      "hazFinish",
      "hazNotamCode",
      "hazNotam",
    ].forEach(function (id) {
      document.getElementById(id).value = "";
    });
    updateHazNextRef(true);
    updateHazSaveButtonState();
  });

  function updateHazLatLonInputs(lat, lon) {
    var latEl = document.getElementById("hazLat");
    var lonEl = document.getElementById("hazLon");
    if (latEl) latEl.value = decToDDM(lat, true);
    if (lonEl) lonEl.value = decToDDM(lon, false);
    if (typeof updateHazDms === "function") updateHazDms();
  }

  function makeHazPreviewIcon() {
    var typeEl = document.getElementById("hazType");
    var type = typeEl ? typeEl.value : "gliding";
    var pinCol = HAZ_PIN_COLORS[type] || "var(--green)";
    var ref = document.getElementById("hazRef") ? document.getElementById("hazRef").value || "" : "";
    return L.divIcon({
      className: "",
      iconSize: [22, 46],
      iconAnchor: [11, 46],
      html:
        '<div class="hazard-pin haz-pick-preview" style="position:relative;display:flex;flex-direction:column;align-items:center;">' +
        '<div style="width:' + Math.max(18,Math.min(84,hazardManualReferences(h).pin.length*6+6)) + 'px;height:18px;border-radius:50%;border:2px solid ' +
        pinCol +
        ";color:" +
        pinCol +
        ';font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;font-family:monospace;flex-shrink:0;background:rgba(0,0,0,.55);">' +
        esc(String(ref)) +
        "</div>" +
        hazardPinSvg(pinCol, type) +
        "</div>",
    });
  }

  function updateHazPickPreviewCircle() {
    if (!hazPickPreviewMarker) return;
    var typeEl = document.getElementById("hazType");
    var type = typeEl ? typeEl.value : "";
    var ll = hazPickPreviewMarker.getLatLng();
    if (!isRadiusHazardType(type)) {
      if (hazPickPreviewCircle) {
        hazardLayer.removeLayer(hazPickPreviewCircle);
        hazPickPreviewCircle = null;
      }
      return;
    }
    var pinCol = HAZ_PIN_COLORS[type] || "var(--red)";
    if (!hazPickPreviewCircle) {
      hazPickPreviewCircle = L.circle(ll, {
        radius: readHazRadiusNm() * 1852,
        color: pinCol,
        weight: 2,
        opacity: 0.85,
        fillColor: pinCol,
        fillOpacity: 0.08,
        dashArray: "6 4",
        interactive: false,
      }).addTo(hazardLayer);
    }
    hazPickPreviewCircle.setLatLng(ll);
    hazPickPreviewCircle.setRadius(readHazRadiusNm() * 1852);
    hazPickPreviewCircle.setStyle({ color: pinCol, fillColor: pinCol });
  }

  function updateHazPickPreview(latlng) {
    if (!latlng && hazPickPreviewMarker) latlng = hazPickPreviewMarker.getLatLng();
    if (!latlng) return;
    if (!hazPickPreviewMarker) {
      hazPickPreviewMarker = L.marker(latlng, {
        icon: makeHazPreviewIcon(),
        zIndexOffset: 6500,
        draggable: true,
      }).addTo(hazardLayer);
      hazPickPreviewMarker.on("drag", function (ev) {
        var ll = ev.target.getLatLng();
        updateHazLatLonInputs(ll.lat, ll.lng);
        updateHazPickPreviewCircle();
      });
      hazPickPreviewMarker.on("dragend", function (ev) {
        var ll = ev.target.getLatLng();
        updateHazLatLonInputs(ll.lat, ll.lng);
        updateHazPickPreviewCircle();
      });
    } else {
      hazPickPreviewMarker.setLatLng(latlng);
      hazPickPreviewMarker.setIcon(makeHazPreviewIcon());
    }
    updateHazPickPreviewCircle();
    setHazSavePickedVisible(false);
    updateHazSaveButtonState();
  }

  function setHazSavePickedVisible(show) {
    // Release074: removed separate Save plotted pin button.
    // The normal ADD HAZARD button now saves picked map coordinates.
  }

  function clearHazPickPreview() {
    if (hazPickPreviewMarker) {
      hazardLayer.removeLayer(hazPickPreviewMarker);
      hazPickPreviewMarker = null;
    }
    if (hazPickPreviewCircle) {
      hazardLayer.removeLayer(hazPickPreviewCircle);
      hazPickPreviewCircle = null;
    }
    setHazSavePickedVisible(false);
  }

  function resetHazardPickingMode() {
    pickingHazard = false;
    var hint = document.getElementById("hazPickHint");
    if (hint) hint.style.display = "none";
    var btn = document.getElementById("hazPick");
    if (btn) btn.textContent = "Pick on map…";
    if (map && map.getContainer) map.getContainer().style.cursor = "";
  }

  document.getElementById("hazPick").addEventListener("click", function () {
    pickingHazard = !pickingHazard;
    document.getElementById("hazPickHint").style.display = pickingHazard
      ? "block"
      : "none";
    this.textContent = pickingHazard ? "Cancel picking" : "Pick on map\u2026";
    map.getContainer().style.cursor = pickingHazard ? "crosshair" : "";
    updateHazSaveButtonState();
  });

  // Release074: separate Save plotted pin button removed.
  // Pick on map fills Lat/Lon; use ADD HAZARD to save to the plotted hazard list.

  function parseDMSHaz(str) {
    if (!str) return NaN;
    str = str.trim().toUpperCase();
    // Matches: N52°38'25" or N052°38'25 or N52 38 25 etc.
    var m = str.match(/^([NSEW])([0-9]+)[^0-9]+([0-9]+)[^0-9]*([0-9]*)/);
    if (m) {
      var hh = m[1],
        deg = parseFloat(m[2]),
        mn = parseFloat(m[3]),
        sec = parseFloat(m[4]) || 0;
      if (isNaN(deg) || isNaN(mn)) return NaN;
      var dec = deg + mn / 60 + sec / 3600;
      return hh === "S" || hh === "W" ? -dec : dec;
    }
    var n = parseFloat(str);
    return isNaN(n) ? NaN : n;
  }
  function updateHazDms() {
    // Inputs now display DMS directly — just hide the old hint element
    var el = document.getElementById("hazDmsHint");
    if (el) el.style.display = "none";
  }
  document.getElementById("hazLat").addEventListener("input", updateHazDms);
  document.getElementById("hazLon").addEventListener("input", updateHazDms);
  // Hemi (E/W) toggle for longitude
  (function () {
    var hemiBtn = document.getElementById("hazLonHemi");
    if (hemiBtn) {
      hemiBtn.addEventListener("click", function () {
        this.dataset.hemi = this.dataset.hemi === "W" ? "E" : "W";
        this.textContent = this.dataset.hemi;
        var inp = document.getElementById("hazLon");
        var d = inp.value.replace(/[^0-9]/g, "");
        if (d) {
          var r = this.dataset.hemi;
          r += d.slice(0, 3);
          if (d.length >= 3) r += "°";
          if (d.length > 3) r += d.slice(3, 5);
          if (d.length >= 5) r += "'";
          if (d.length > 5) r += d.slice(5, 7);
          if (d.length >= 7) r += '"';
          inp.value = r;
        }
      });
    }
    // Latitude auto-format keydown: N##°##'##"
    var latInp = document.getElementById("hazLat");
    if (latInp) {
      latInp.addEventListener("focus", function () {
        if (!this.value) this.value = "N";
      });
      latInp.addEventListener("keydown", function (e) {
        if (e.metaKey || e.ctrlKey || e.key === "Tab") return;
        var d = this.value.replace(/[^0-9]/g, "");
        if (e.key === "Backspace") {
          e.preventDefault();
          d = d.slice(0, -1);
          var r = "N";
          r += d.slice(0, 2);
          if (d.length >= 2) r += "°";
          if (d.length > 2) r += d.slice(2, 4);
          if (d.length >= 4) r += "'";
          if (d.length > 4) r += d.slice(4, 6);
          if (d.length >= 6) r += '"';
          this.value = r || "N";
          return;
        }
        if (!/^[0-9]$/.test(e.key)) {
          e.preventDefault();
          return;
        }
        e.preventDefault();
        if (d.length >= 6) return;
        d += e.key;
        var r = "N";
        r += d.slice(0, 2);
        if (d.length >= 2) r += "°";
        if (d.length > 2) r += d.slice(2, 4);
        if (d.length >= 4) r += "'";
        if (d.length > 4) r += d.slice(4, 6);
        if (d.length >= 6) r += '"';
        this.value = r;
      });
    }
    // Longitude auto-format keydown: [EW]###°##'##"
    var lonInp = document.getElementById("hazLon");
    if (lonInp) {
      lonInp.addEventListener("keydown", function (e) {
        if (e.metaKey || e.ctrlKey || e.key === "Tab") return;
        var hBtn = document.getElementById("hazLonHemi");
        var hemi = hBtn ? hBtn.dataset.hemi : "W";
        var d = this.value.replace(/[^0-9]/g, "");
        if (e.key === "Backspace") {
          e.preventDefault();
          d = d.slice(0, -1);
          var r = hemi;
          r += d.slice(0, 3);
          if (d.length >= 3) r += "°";
          if (d.length > 3) r += d.slice(3, 5);
          if (d.length >= 5) r += "'";
          if (d.length > 5) r += d.slice(5, 7);
          if (d.length >= 7) r += '"';
          this.value = r || "";
          return;
        }
        if (!/^[0-9]$/.test(e.key)) {
          e.preventDefault();
          return;
        }
        e.preventDefault();
        if (d.length >= 7) return;
        d += e.key;
        var r = hemi;
        r += d.slice(0, 3);
        if (d.length >= 3) r += "°";
        if (d.length > 3) r += d.slice(3, 5);
        if (d.length >= 5) r += "'";
        if (d.length > 5) r += d.slice(5, 7);
        if (d.length >= 7) r += '"';
        this.value = r;
      });
    }
  })();
  document.getElementById("hazExport").addEventListener("click", function () {
    var blob = new Blob([JSON.stringify(hazards, null, 2)], {
      type: "application/json",
    });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "fiso-radar-hazards.json";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  });
  document
    .getElementById("hazImportBtn")
    .addEventListener("click", function () {
      document.getElementById("hazImportFile").click();
    });
  document
    .getElementById("hazImportFile")
    .addEventListener("change", function (e) {
      var file = e.target.files[0];
      if (!file) return;
      var reader = new FileReader();
      reader.onload = function () {
        try {
          var data = JSON.parse(reader.result);
          if (!Array.isArray(data)) throw new Error("not an array");
          data.forEach(function (h) {
            if (
              typeof h.lat === "number" &&
              typeof h.lon === "number" &&
              h.startISO &&
              h.finishISO
            ) {
              hazards.push({
                id: h.id || uid(),
                type: h.type === "parachute" ? "parachute" : "gliding",
                ref: h.ref || 1,
                lat: h.lat,
                lon: h.lon,
                lower: h.lower || "",
                upper: h.upper || "",
                startISO: h.startISO,
                finishISO: h.finishISO,
                notam: h.notam || "",
              });
            }
          });
          saveJSON(LS_KEY_HAZARDS, hazards);
          renderHazards();
        } catch (err) {
          alert("Could not read that file as a hazards JSON export.");
        }
        e.target.value = "";
      };
      reader.readAsText(file);
    });

  /* ============================ NOTAMs ============================ */
  var Q_COORD_RE = /^(\d{2})(\d{2})([NS])(\d{3})(\d{2})([EW])(\d{3})$/;
  var NOTAM_START_RE = /(?=(?:^|\n)\(?\s*[A-Z]\d{3,4}\/\d{2}\s+NOTAM[NRC])/g;

  function parsePibDateTimeUtc(dateStr, timeStr) {
    var ds = String(dateStr || "").trim().toUpperCase();
    var ts = String(timeStr || "").replace(/UTC/i, "").trim();
    var m = ds.match(/^(\d{2})\s+([A-Z]{3})\s+(\d{4})$/);
    var t = ts.match(/^(\d{2}):(\d{2})$/);
    if (!m || !t) return null;
    var months = { JAN:0,FEB:1,MAR:2,APR:3,MAY:4,JUN:5,JUL:6,AUG:7,SEP:8,OCT:9,NOV:10,DEC:11 };
    if (months[m[2]] === undefined) return null;
    return new Date(Date.UTC(parseInt(m[3],10), months[m[2]], parseInt(m[1],10), parseInt(t[1],10), parseInt(t[2],10)));
  }

  function pibOperationalStatus() {
    if (!currentPib || !currentPib.meta) return { state:"empty", label:"NO ACTIVE PIB" };
    var m = currentPib.meta || {};
    var now = new Date();
    var pibDate = parsePibDateTimeUtc(m.pibDate, m.pibTime);
    var outOfDate = false;
    if (pibDate) {
      outOfDate = now.getUTCFullYear() !== pibDate.getUTCFullYear() || now.getUTCMonth() !== pibDate.getUTCMonth() || now.getUTCDate() !== pibDate.getUTCDate();
    } else if (m.importedAt) {
      var imp = new Date(m.importedAt);
      if (!isNaN(imp.getTime())) outOfDate = now.getUTCFullYear() !== imp.getUTCFullYear() || now.getUTCMonth() !== imp.getUTCMonth() || now.getUTCDate() !== imp.getUTCDate();
    }
    return outOfDate ? { state:"outdated", label:"OUT OF DATE — upload today's PIB" } : { state:"current", label:"CURRENT" };
  }

  function updatePibSummary() {
    var el = document.getElementById("pibSummary");
    var card = document.getElementById("activePibCard");
    if (!el) return;
    el.style.whiteSpace = "pre-line";
    if (card) card.className = "active-pib-card";
    if (!currentPib || !currentPib.meta) {
      el.textContent = "ACTIVE PIB\nNone loaded\nStatus: NO ACTIVE PIB";
      if (card) card.classList.add("empty");
      return;
    }
    var m = currentPib.meta;
    var status = pibOperationalStatus();
    if (card) card.classList.add(status.state);
    var count = Array.isArray(currentPib.notams) ? currentPib.notams.length : 0;
    var lines = [];
    lines.push("ACTIVE PIB");
    if (m.pibDate) lines.push(m.pibDate);
    lines.push(count + " NOTAM" + (count === 1 ? "" : "s") + (m.reportReference ? " — " + m.reportReference : ""));
    if (m.validity) lines.push("Valid: " + m.validity);
    else if (m.pibDate) lines.push("Valid until: " + m.pibDate + " 23:59 UTC");
    if (m.heightLower || m.heightUpper) {
      lines.push("LEVELS: LOWER " + (m.heightLower || "---") + "; UPPER " + (m.heightUpper || "---"));
    } else if (m.heightLimits) {
      var parts = String(m.heightLimits || "").match(/(\d{3})\s*\/\s*(\d{3})/);
      if (parts) lines.push("LEVELS: LOWER " + parts[1] + "; UPPER " + parts[2]);
      else lines.push("LEVELS: " + m.heightLimits);
    }
    if (m.pibTime) lines.push("Uploaded: " + m.pibTime);
    lines.push("Status: " + (status.state === "current" ? "🟢 " : "🟠 ") + status.label);
    el.textContent = lines.join("\n");
  }

  function notamIsExpired(n, nowMs) {
    if (!n) return false;
    var c = String(n.c || "").trim().toUpperCase();
    if (!c || c === "PERM") return false;
    var cIso = hazardNotamDateIso(c);
    if (!cIso) return false;
    var endMs = new Date(cIso).getTime();
    return !isNaN(endMs) && Number(nowMs) >= endMs;
  }

  function getCurrentPibNotams() {
    // DEV419: the ACTIVE PIB is authoritative, but expired NOTAMs are never
    // exposed to operational consumers. Item C is the hard end-of-validity.
    var rows = currentPib && Array.isArray(currentPib.notams) ? currentPib.notams : [];
    var now = window.ffappNowMs ? window.ffappNowMs() : Date.now();
    return rows.filter(function(n){ return !notamIsExpired(n, now); }).map(function(n){
      return window.FFAPP_NOTAM_ENGINE.repairPreparedSchedule(n);
    });
  }


  /* Release343 — bottom ticker for active aerodrome and LARS closures.
     This deliberately reads only the ACTIVE PIB. B/C are the hard validity
     envelope and D) is honoured when it contains a recurring UTC schedule. */
  function closureTickerAirportName(icao) {
    icao = String(icao || "").toUpperCase().trim();
    if (!icao) return "";
    try {
      var hit = (Array.isArray(UK_AIRPORTS_DEFAULT) ? UK_AIRPORTS_DEFAULT : []).find(function(a){
        return String(a && a.icao || "").toUpperCase() === icao;
      });
      return hit && hit.name ? String(hit.name) : "";
    } catch (_) { return ""; }
  }

