      if(!currentPib||!Array.isArray(currentPib.notams))throw new Error('No PIB data is loaded yet. Wait for the live PIB to load, then try again.');
      var day=new Date().toISOString().slice(0,10),all=currentPib.notams;
      if(!todaysNotamsCache||todaysNotamsCache.source!==all||todaysNotamsCache.length!==all.length||todaysNotamsCache.day!==day){
        todaysNotamsCache={source:all,length:all.length,day:day,classified:classifyTodaysNotams(all.filter(function(n){return !notamIsExpired(n,Date.now());}))};
      }
      var health=loadLivePibHealth(),meta=currentPib.meta||{};
      var options={now:Date.now(),areas:window.HAZDAM&&window.HAZDAM.staticAreas||{},issued:meta.pibIssued||health.pibIssued||'',checked:Date.parse(health.lastChecked)>Date.parse(meta.feedCheckedAt)?health.lastChecked:meta.feedCheckedAt||health.lastChecked||'',
        solar:function(n,c,date,rise){return hazdamSolarUtcMinutes(new Date(date+43200000),c&&c.lat!=null?c.lat:n.lat,c&&c.lon!=null?c.lon:n.lon,rise);}};
      var report=window.FFAPP_TODAYS_NOTAMS.build(todaysNotamsCache.classified,options);report.feedWarning=health.state==='error'?'The app’s latest PIB check failed. Last valid data retained.':'';
      var changes=centralNotamReport&&String(centralNotamReport.asOf).slice(0,10)===day?centralNotamReport.changes:[];
      var cancelled=Object.create(null);
      all.concat(changes.map(function(x){return x.n;})).forEach(function(n){var proof=window.FFAPP_NOTAM_HISTORY.verifyCancellation(n);if(proof.verified)cancelled[proof.cancelledNotamId]=true;});
      var originals=changes.map(function(x){return x.n;}).filter(function(n){return cancelled[window.FFAPP_NOTAM_HISTORY.reference(n.notamId)];});
      var prior=null,stateKey='fiso_today_notams_state_v1:'+day;
      try{prior=JSON.parse(localStorage.getItem(stateKey)||'null');}catch(e){}
      report=window.FFAPP_TODAYS_NOTAMS.reconcile(report,prior,{records:all,changes:changes,originals:window.FFAPP_TODAYS_NOTAMS.build(classifyTodaysNotams(originals),options).rows});
      localStorage.setItem(stateKey,JSON.stringify(report));
