  function parseNotamBlock(block) {
    var idM = block.match(/([A-Z]\d{3,4}\/\d{2})\s+NOTAM([NRC])/);
    var qM = block.match(/Q\)\s*([^\n\r]+)/);
    var aM = block.match(/A\)\s*([^\n\r]+)/);
    var bM = block.match(/B\)\s*([^\n\r]+)/);
    var cM = block.match(/C\)\s*([^\n\r]+)/);
    var dM = block.match(/D\)\s*([\s\S]*?)(?=\n\s*E\)|$)/);
    var eM = block.match(/E\)\s*([\s\S]*?)(?=\n\s*F\)|\n\s*G\)|\n\)|\s*$)/);

    var rec = {
      id: uid(),
      notamId: idM ? idM[1] : "UNKNOWN",
      fir: aM ? aM[1].trim() : "",
      b: bM ? bM[1].trim() : "",
      c: cM ? cM[1].trim() : "",
      d: dM ? dM[1].trim() : "",
      eText: eM ? eM[1].trim().replace(/\s+/g, " ") : "",
      raw: block.trim(),
      lat: null,
      lon: null,
      radiusNm: null,
      lower: null,
      upper: null,
    };

    if (qM) {
      var fields = qM[1].split("/").map(function (s) {
        return s.trim();
      });
      if (fields.length >= 8) {
        rec.lower = fields[5];
        rec.upper = fields[6];
        var coordMatch = fields[7].match(Q_COORD_RE);
        if (coordMatch) {
          var latDeg = parseInt(coordMatch[1], 10),
            latMin = parseInt(coordMatch[2], 10);
          var ns = coordMatch[3];
          var lonDeg = parseInt(coordMatch[4], 10),
            lonMin = parseInt(coordMatch[5], 10);
          var ew = coordMatch[6];
          var radius = parseInt(coordMatch[7], 10);
          var lat = latDeg + latMin / 60;
          if (ns === "S") lat = -lat;
          var lon = lonDeg + lonMin / 60;
          if (ew === "W") lon = -lon;
          rec.lat = lat;
          rec.lon = lon;
          rec.radiusNm = radius;
        }
      }
    }
    return rec;
  }

