  function normalizeAirfieldName(s) {
    return String(s || "")
      .toLowerCase()
      .replace(/[^a-z0-9]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }
  function phoneDbLookup(name) {
    var norm = normalizeAirfieldName(name);
    for (var i = 0; i < PHONE_DB.length; i++) {
      if (normalizeAirfieldName(PHONE_DB[i].n) === norm) return PHONE_DB[i].p;
    }
    for (var i = 0; i < PHONE_DB.length; i++) {
      var pn = normalizeAirfieldName(PHONE_DB[i].n);
      if (norm.indexOf(pn) !== -1 || pn.indexOf(norm) !== -1)
        return PHONE_DB[i].p;
    }
    return null;
  }
  function applyPhoneDbToAirports() {
    var changed = false;
    UK_AIRPORTS_DEFAULT.forEach(function (apt) {
      var over = airportOverrides[apt.icao] || {};
      if (over.tel) return;
      var phone = phoneDbLookup(apt.name);
      if (phone) {
        over.tel = phone;
        airportOverrides[apt.icao] = over;
        changed = true;
      }
    });
    if (changed) {
      saveJSON(LS_KEY_AIRPORTS, airportOverrides);
      renderAirportMarkers();
    }
  }

