  // Merge saved overrides (user-edited tel/freq) with defaults
  var airportOverrides = loadJSON(LS_KEY_AIRPORTS, {});
  var LS_KEY_UNIFIED_AIRFIELDS = "fisoradar_airfields_unified_v1";

  // One master airfield dataset: migrate the built-in UK airport directory and
  // any previously uploaded airfields into the Airfield information list once.
  function initialiseUnifiedAirfields() {
    if (loadJSON(LS_KEY_UNIFIED_AIRFIELDS, false)) return;
    var merged = [];
    var byKey = {};
    function keyFor(a) {
      var icao = String((a && a.icao) || "").trim().toUpperCase();
      if (icao) return "I:" + icao;
      return "N:" + normalizeAirfieldName((a && a.name) || "");
    }
    UK_AIRPORTS_DEFAULT.forEach(function (apt) {
      var over = airportOverrides[apt.icao] || {};
      var row = Object.assign({}, apt, over);
      row.phone = row.tel || row.phone || "";
      row.tel = row.phone;
      var k = keyFor(row);
      byKey[k] = merged.length;
      merged.push(row);
    });
    (Array.isArray(airfields) ? airfields : []).forEach(function (a) {
      var row = Object.assign({}, a);
      row.icao = String(row.icao || "").trim().toUpperCase();
      row.phone = row.phone || row.tel || "";
      row.tel = row.phone;
      var k = keyFor(row);
      if (k && byKey[k] !== undefined) merged[byKey[k]] = Object.assign({}, merged[byKey[k]], row);
      else { byKey[k] = merged.length; merged.push(row); }
    });
    airfields = merged;
    saveJSON(LS_KEY_AIRFIELDS, airfields);
    saveJSON(LS_KEY_UNIFIED_AIRFIELDS, true);
  }
  initialiseUnifiedAirfields();
  function getAirportData() {
    // DEV418: merge every AIRAC 09/2026 AIP AD 2 aerodrome into the map data.
    // Existing app airfields are retained; AIP coordinates/data take priority for matching ICAO codes.
    var byCode = {};
    (Array.isArray(airfields) ? airfields : []).forEach(function (apt) {
      var row = Object.assign({}, apt);
      row.icao = String(row.icao || "").trim().toUpperCase();
      row.tel = row.tel || row.phone || ""; row.phone = row.phone || row.tel || "";
      if (row.icao) byCode[row.icao] = row;
    });
    var aipDb = window.FFAPP_AIP_AIRFIELDS || {};
    Object.keys(aipDb).forEach(function(code){
      var a=aipDb[code];
      byCode[code]=Object.assign({},byCode[code]||{}, {icao:code,name:a.name,lat:a.lat,lon:a.lon,aip:true});
    });
    var result = Object.keys(byCode).map(function(k){return byCode[k];}).filter(function (apt) {
      return typeof apt.lat === "number" && typeof apt.lon === "number" && !isNaN(apt.lat) && !isNaN(apt.lon);
    });
    return window.FISO_AIRFIELD_INFO ? window.FISO_AIRFIELD_INFO.apply(result) : result;
  }
  function saveAirportOverride(icao, data) {
    icao = String(icao || "").trim().toUpperCase();
    airportOverrides[icao] = data;
    saveJSON(LS_KEY_AIRPORTS, airportOverrides);
    var idx = airfields.findIndex(function (a) { return String(a.icao || "").trim().toUpperCase() === icao; });
    if (idx >= 0) {
      airfields[idx] = Object.assign({}, airfields[idx], data, { icao: icao, phone: data.tel || data.phone || "", tel: data.tel || data.phone || "" });
      saveJSON(LS_KEY_AIRFIELDS, airfields);
      renderAirfields();
      renderAirportMarkers();
    }
  }

  var airportMarkers = {};
  var airportLayer = L.layerGroup().addTo(map);

  // DEV392: current UK airfield layer.
  // Primary data is the current public-domain OurAirports UK subset, refreshed daily
  // through a Netlify function. 2017 LAAS points are retained only as a legacy fallback
  // where no current airfield is close enough to represent the same site.
  var REFERENCE_AIRFIELD_DOT_MIN_ZOOM = 9;
  var LAAS_AIRFIELD_NAME_MIN_ZOOM = 11;
  var CURRENT_AIRFIELD_CACHE_KEY = "ffapp_current_uk_airfields_v392";
  var CURRENT_AIRFIELD_CACHE_MAX_AGE = 24 * 60 * 60 * 1000;
  var laasAirfieldLayer = L.layerGroup().addTo(map);
  var laasAirfieldMarkers = [];
  window.CURRENT_UK_AIRFIELDS = Array.isArray(window.CURRENT_UK_AIRFIELDS) ? window.CURRENT_UK_AIRFIELDS : [];

  function laasAirfieldLocLabel(code) {
    var labels = {R:"Runway midpoint",H:"Helipad",E:"Entrance",P:"Parking area",S:"Spectator area",V:"Viewing point","?":"Approximate location"};
    return labels[String(code || "")] || "Published location";
  }

  function currentAirfieldTypeLabel(type) {
    var labels = {
      large_airport:"Large airport", medium_airport:"Medium airport", small_airport:"Airfield",
      heliport:"Heliport", seaplane_base:"Seaplane base", balloonport:"Balloon site"
    };
    return labels[String(type || "")] || "Airfield";
  }

  function currentAirfieldPopupHtml(a) {
    if(window.FISO_AIRFIELD_INFO) a=window.FISO_AIRFIELD_INFO.applyOne(a);
    if(!a)return '';
    var savedInfo=window.FISO_AIRFIELD_INFO ? window.FISO_AIRFIELD_INFO.detailsHtml(a)+window.FISO_AIRFIELD_INFO.buttonHtml(a) : '';
    var codes=[];
    if (a.icao) codes.push(String(a.icao).toUpperCase());
    if (a.iata && codes.indexOf(String(a.iata).toUpperCase())<0) codes.push(String(a.iata).toUpperCase());
    if (a.ident && codes.indexOf(String(a.ident).toUpperCase())<0) codes.push(String(a.ident).toUpperCase());
    return '<div class="pop"><h3>' + esc(a.name || a.icao || a.ident || "Airfield") + '</h3>' +
      (codes.length ? '<div class="row"><span class="pl">Code</span><span>' + esc(codes.join(' · ')) + '</span></div>' : '') +
      '<div class="row"><span class="pl">Position</span><span>' + Number(a.lat).toFixed(4) + ', ' + Number(a.lon).toFixed(4) + '</span></div>' +
      '<div class="row"><span class="pl">Type</span><span>' + esc(currentAirfieldTypeLabel(a.type)) + '</span></div>' +
      (a.municipality ? '<div class="row"><span class="pl">Location</span><span>' + esc(a.municipality) + '</span></div>' : '') +
      '<div class="row"><span class="pl">Source</span><span>OurAirports current UK dataset</span></div>' +
      savedInfo+'</div>';
  }

  function laasAirfieldPopupHtml(a) {
    if(window.FISO_AIRFIELD_INFO) a=window.FISO_AIRFIELD_INFO.applyOne(a);
    if(!a)return '';
    var savedInfo=window.FISO_AIRFIELD_INFO ? window.FISO_AIRFIELD_INFO.detailsHtml(a)+window.FISO_AIRFIELD_INFO.buttonHtml(a) : '';
    return '<div class="pop"><h3>' + esc(a.name || "Airfield") + '</h3>' +
      '<div class="row"><span class="pl">Position</span><span>' + Number(a.lat).toFixed(4) + ', ' + Number(a.lon).toFixed(4) + '</span></div>' +
      '<div class="row"><span class="pl">Guide point</span><span>' + esc(laasAirfieldLocLabel(a.loc)) + '</span></div>' +
      '<div class="row"><span class="pl">Source</span><span>LAAS May 2017 · legacy fallback</span></div>' +
      savedInfo+'</div>';
  }

  function normaliseAirfieldName(name) {
    return String(name || "").toUpperCase()
      .replace(/\b(AIRPORT|AERODROME|AIRFIELD|HELIPORT|INTERNATIONAL|RAF|RNAS)\b/g, " ")
      .replace(/[^A-Z0-9]+/g, " ").replace(/\s+/g, " ").trim();
  }

  function airfieldDistanceNm(a,b) {
    var R=3440.065, r=Math.PI/180;
    var p1=Number(a.lat)*r, p2=Number(b.lat)*r, dp=(Number(b.lat)-Number(a.lat))*r, dl=(Number(b.lon)-Number(a.lon))*r;
    var h=Math.sin(dp/2)*Math.sin(dp/2)+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)*Math.sin(dl/2);
    return 2*R*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));
  }

  function isLaasDuplicateOfCurrent(legacy, currentList) {
    var ln=normaliseAirfieldName(legacy.name);
    for (var i=0;i<currentList.length;i++) {
      var c=currentList[i], d=airfieldDistanceNm(legacy,c);
      if (d <= 0.45) return true;
      var cn=normaliseAirfieldName(c.name);
      if (ln && cn && (ln===cn || ln.indexOf(cn)>=0 || cn.indexOf(ln)>=0) && d <= 5) return true;
    }
    return false;
  }

  var referenceAirfieldsDirty = true;
  var referenceAirfieldEntries = new Map();
  var referenceDuplicateSource = null, referenceDuplicateCount = 0, referenceDuplicateCache = new WeakMap(), referenceEditEdition = -1;
  function referenceAirfieldIsVisible(a, bounds) {
    if(!a || typeof a!=="object" || a.lat==null || a.lon==null)return false;
    var lat=Number(a.lat),lon=Number(a.lon);
    return isFinite(lat)&&Math.abs(lat)<=90&&isFinite(lon)&&Math.abs(lon)<=180&&bounds.contains([lat,lon]);
  }
  // DEV467 AIRFIELD HOVER BEGIN
  function wireAirfieldHover(marker,airfield){
    var hover=null;
    function hide(){if(hover){hover.remove();hover=null;}}
    marker.on('mouseover',function(){
      hide();var a=window.FISO_AIRFIELD_INFO?window.FISO_AIRFIELD_INFO.applyOne(airfield):airfield;if(!a)return;
      var code=String(a.icao||'').toUpperCase(),aip=(window.FFAPP_AIP_AIRFIELDS||{})[code];
      hover=L.tooltip({direction:'top',offset:[0,-9],opacity:1,className:'airfield-hover-bubble',interactive:false})
        .setLatLng(marker.getLatLng()).setContent(window.FISO_AIRFIELD_MAP_LABELS.html(a,aip)).addTo(map);
    });
    marker.on('mouseout remove popupopen',hide);
  }
  // DEV467 AIRFIELD HOVER END

  function updateReferenceAirfieldLabel(marker, showNames) {
    if(showNames) {
      if(!marker.getTooltip()) marker.bindTooltip(marker._referenceLabel, {
        permanent:true,direction:'top',offset:[0,-3],opacity:1,className:'laas-airfield-label'
      });
    } else if(marker.getTooltip()) marker.unbindTooltip();
  }
  function refreshLaasAirfieldLabels() {
    var zoom = map.getZoom();
    if (referenceAirfieldsDirty && zoom >= REFERENCE_AIRFIELD_DOT_MIN_ZOOM &&
        (!settings || !settings.layers || settings.layers.airfields !== false)) {
      renderLaasAirfields();
      return;
    }
    var showDots = zoom >= REFERENCE_AIRFIELD_DOT_MIN_ZOOM;
    var airfieldsEnabled = !settings || !settings.layers || settings.layers.airfields !== false;

    var showNames = showDots && zoom >= LAAS_AIRFIELD_NAME_MIN_ZOOM;
    laasAirfieldMarkers.forEach(function(m) { updateReferenceAirfieldLabel(m,showNames); });

    // DEV393: keep regional views uncluttered. The dense current/legacy reference
    // airfield layer is completely hidden until zoom 9, then dots appear. Names
    // remain suppressed until zoom 11. The user's Airfields layer toggle still wins.
    if (showDots && airfieldsEnabled) {
      if (!map.hasLayer(laasAirfieldLayer)) map.addLayer(laasAirfieldLayer);
    } else {
      if (map.hasLayer(laasAirfieldLayer)) map.removeLayer(laasAirfieldLayer);
    }

  }

  function addReferenceAirfieldMarker(a, isCurrent) {
    var lat=Number(a.lat), lon=Number(a.lon);
    if (!isFinite(lat) || !isFinite(lon)) return;
    var m=L.circleMarker([lat,lon],{
      radius:isCurrent ? 2.9 : 2.4,
      color:isCurrent ? '#0f4b67' : '#596d76',
      weight:1,
      opacity:isCurrent ? 0.95 : 0.72,
      fillColor:isCurrent ? '#6fe0ff' : '#a8b7bd',
      fillOpacity:isCurrent ? 0.86 : 0.58,
      interactive:true
    });
    m.bindPopup(function(){ return isCurrent ? currentAirfieldPopupHtml(a) : laasAirfieldPopupHtml(a); }, {maxWidth:300});
    m._referenceLabel=esc((a.icao ? window.FISO_AIRFIELD_MAP_LABELS.code(a) + ' ' : '') + (a.name || a.ident || "Airfield"));
    wireAirfieldHover(m,a);
    // Do not open then close permanent tooltips below their visibility threshold.
    updateReferenceAirfieldLabel(m,map.getZoom()>=LAAS_AIRFIELD_NAME_MIN_ZOOM);
    m.addTo(laasAirfieldLayer);
    return m;
  }

  function renderLaasAirfields() {
    referenceAirfieldsDirty = true;
    if (map.getZoom() < REFERENCE_AIRFIELD_DOT_MIN_ZOOM ||
        (settings && settings.layers && settings.layers.airfields === false)) {
      if(map.hasLayer(laasAirfieldLayer))map.removeLayer(laasAirfieldLayer);
      return;
    }
    referenceAirfieldsDirty = false;
    var currentSource=Array.isArray(window.CURRENT_UK_AIRFIELDS) ? window.CURRENT_UK_AIRFIELDS : [];
    var edits=window.FISO_AIRFIELD_INFO, current=edits ? edits.apply(currentSource) : currentSource;
    var edition=edits ? edits.edition : 0;
    if(referenceDuplicateSource!==currentSource||referenceDuplicateCount!==current.length||referenceEditEdition!==edition){referenceDuplicateSource=currentSource;referenceDuplicateCount=current.length;referenceEditEdition=edition;referenceDuplicateCache=new WeakMap();}
    var bounds=map.getBounds().pad(0.15),visible=new Map();
    current.forEach(function(a){if(referenceAirfieldIsVisible(a,bounds))visible.set(a,true);});
    (Array.isArray(window.LAAS_AIRFIELDS_2017) ? window.LAAS_AIRFIELDS_2017 : []).forEach(function(a){
      if(edits)a=edits.applyOne(a);
      if(!referenceAirfieldIsVisible(a,bounds))return;
      if(!referenceDuplicateCache.has(a))referenceDuplicateCache.set(a,isLaasDuplicateOfCurrent(a,current));
      if(!referenceDuplicateCache.get(a))visible.set(a,false);
    });
    referenceAirfieldEntries.forEach(function(entry,a){
      if(!visible.has(a)||visible.get(a)!==entry.current){laasAirfieldLayer.removeLayer(entry.marker);referenceAirfieldEntries.delete(a);}
    });
    visible.forEach(function(isCurrent,a){
      if(!referenceAirfieldEntries.has(a))referenceAirfieldEntries.set(a,{current:isCurrent,marker:addReferenceAirfieldMarker(a,isCurrent)});
    });
    laasAirfieldMarkers=Array.from(referenceAirfieldEntries.values(),function(entry){return entry.marker;});
    refreshLaasAirfieldLabels();
  }

  function loadCachedCurrentAirfields() {
    try {
      var cached=JSON.parse(localStorage.getItem(CURRENT_AIRFIELD_CACHE_KEY)||"null");
      if (cached && Array.isArray(cached.airfields) && Number(cached.savedAt)>0) {
        window.CURRENT_UK_AIRFIELDS=cached.airfields;
        return (Date.now()-Number(cached.savedAt)) < CURRENT_AIRFIELD_CACHE_MAX_AGE;
      }
    } catch(e) {}
    return false;
  }

  function fetchCurrentUkAirfields(force) {
    var fresh=loadCachedCurrentAirfields();
    renderLaasAirfields();
    if (fresh && !force) return;
    fetch('/.netlify/functions/current-airfields',{headers:{'Accept':'application/json'}})
      .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
      .then(function(data){
        if (!data || !Array.isArray(data.airfields) || !data.airfields.length) throw new Error('No current airfields returned');
        window.CURRENT_UK_AIRFIELDS=data.airfields;
        try { localStorage.setItem(CURRENT_AIRFIELD_CACHE_KEY,JSON.stringify({savedAt:Date.now(),airfields:data.airfields})); } catch(e) {}
        renderLaasAirfields();
      })
      .catch(function(err){
        console.warn('Current UK airfield update unavailable; using cached/LAAS fallback.',err);
      });
  }

  map.on('zoomend moveend resize', renderLaasAirfields);
  // DEV439: retain cached reference data immediately; let the first basemap tile
  // arrive before competing for bandwidth with the optional directory refresh.
  loadCachedCurrentAirfields();
  renderLaasAirfields();
  var referenceRefreshStarted = false;
  var referenceRefreshTimer;
  function startReferenceAirfieldRefresh() {
    if (referenceRefreshStarted) return;
    referenceRefreshStarted = true;
    clearTimeout(referenceRefreshTimer);
    tileStandard.off('tileload', startReferenceAirfieldRefresh);
    map.off('zoomend', refreshReferenceAirfieldsIfVisible);
    fetchCurrentUkAirfields(false);
  }
  function refreshReferenceAirfieldsIfVisible() {
    if (map.getZoom() >= REFERENCE_AIRFIELD_DOT_MIN_ZOOM && settings.layers.airfields !== false)
      startReferenceAirfieldRefresh();
  }
  referenceRefreshTimer = setTimeout(startReferenceAirfieldRefresh, 4000);
  tileStandard.once('tileload', startReferenceAirfieldRefresh);
  map.on('zoomend', refreshReferenceAirfieldsIfVisible);
  refreshReferenceAirfieldsIfVisible();

  // Release 273 — Southampton Frequency Monitoring Code (FMC) attention layer.
  // Boundary amended by C4906/26 (PERM), UK AIP EGHI AD 2.22-7 / ENR 6-80.
  var SOUTHAMPTON_FMC_COORDS = [
    [51.17527778, -1.33916667],
    [51.11333333, -1.04222222],
    [50.97666667, -0.98222222],
    [50.78222222, -0.94055556],
    [50.57638889, -1.29805556],
    [50.66250000, -1.59138889],
    [50.70805556, -1.55027778],
    [50.91166667, -1.65694444],
    [51.02444444, -1.57222222],
    [51.17527778, -1.33916667]
  ];
  var southamptonFmcLayer = null;
  var southamptonFmcHideTimer = null;

  function ensureSouthamptonFmcLayer() {
    if (southamptonFmcLayer) return southamptonFmcLayer;
    southamptonFmcLayer = L.polygon(SOUTHAMPTON_FMC_COORDS, {
      pane: "overlayPane",
      color: "#d9b900",
      weight: 2,
      opacity: 0.9,
      fillColor: "#fff3a6",
      fillOpacity: 0.32,
      interactive: false
    });
    southamptonFmcLayer.bindTooltip(
      '<div class="southampton-fmc-info">' +
      '<b>SOUTHAMPTON FMC</b><br>' +
      'SSR 7011<br>' +
      'Monitor SOLENT RADAR<br>' +
      '<b>120.230 MHz</b>' +
      '</div>',
      { permanent: true, direction: "center", className: "southampton-fmc-tooltip", opacity: 1 }
    );
    return southamptonFmcLayer;
  }

  function showSouthamptonFmc() {
    if (southamptonFmcHideTimer) {
      clearTimeout(southamptonFmcHideTimer);
      southamptonFmcHideTimer = null;
    }
    var layer = ensureSouthamptonFmcLayer();
    if (!map.hasLayer(layer)) layer.addTo(map);
  }

  function hideSouthamptonFmcAfterDelay() {
    if (southamptonFmcHideTimer) clearTimeout(southamptonFmcHideTimer);
    southamptonFmcHideTimer = setTimeout(function () {
      if (southamptonFmcLayer && map.hasLayer(southamptonFmcLayer)) {
        map.removeLayer(southamptonFmcLayer);
      }
      southamptonFmcHideTimer = null;
    }, 5000);
  }

  // DEV416 — AIP operational-information popup prototype.
  // Four representative AIP aerodromes are populated so the operational layout can be assessed
  // before rolling the design out across the complete UK AIP aerodrome set.
