      freqs: [{service:"SOLENT RADAR",callsign:"SOLENT RADAR",channel:"120.230"},{service:"TOWER",callsign:"SOUTHAMPTON TOWER",channel:"118.205"},{service:"APP",callsign:"SOUTHAMPTON RADAR",channel:"122.730"},{service:"ATIS",callsign:"SOUTHAMPTON INFORMATION",channel:"130.880"}],
