  /* ---- Release111: admin-only full clear of plotted NOTAMs ---- */
  function clearAllPlottedNotamsAndResetRefs() {
    window.__FFAPP_CLEARING_PLOTTED_NOTAMS = true;

    // Clear every runtime collection used for manually plotted/parsed NOTAMs.
    hazards = [];
    notams = [];

    // Remove all visible map objects immediately, rather than relying only on
    // a later render pass. This includes pins, polygons, circles and labels.
    try { if (hazardLayer && hazardLayer.clearLayers) hazardLayer.clearLayers(); } catch (e) {}
    try { if (notamLayer && notamLayer.clearLayers) notamLayer.clearLayers(); } catch (e) {}
    hazardMarkers = {};
    hazardShapes = {};
    hazardRadiusShapes = {};

    // Persist the empty local state before Firebase is updated.
    try { localStorage.setItem(LS_KEY_HAZARDS, "[]"); } catch (e) {}
    try { localStorage.setItem(LS_KEY_NOTAMS, "[]"); } catch (e) {}
    try { localStorage.setItem(LS_KEY_HAZARD_PIN_RESET_DATE, utcHazardResetDateKey()); } catch (e) {}

    hazEditing = null;
    hazBufConflicts = {};
    hazBufAcInfo = {};
    hazAcked = {};
    activeHazardPointLabels = [];
    try { if (typeof clearHazPickPreview === "function") clearHazPickPreview(); } catch (e) {}
    try { if (typeof clearActiveHazardPointLabels === "function") clearActiveHazardPointLabels(); } catch (e) {}
    try { if (typeof clearHazardEditBoxHighlight === "function") clearHazardEditBoxHighlight(); } catch (e) {}

    // Reset the form and counters. The stored baseline is zero; the input shows
    // 1 because that is the next new pin number.
    var refInput = document.getElementById("hazRef");
    if (refInput) refInput.value = "1";
    try { if (typeof updateHazNextRef === "function") updateHazNextRef(true); } catch (e) {}

    // Re-render lists/counters from the now-empty arrays.
    try { if (typeof renderHazards === "function") renderHazards(); } catch (e) {}
    try { if (typeof renderNotams === "function") renderNotams(); } catch (e) {}

    // Use a tombstone object instead of remove(). Firebase represents an empty
    // array as null, and the old null-listener could reseed stale local data.
    // A tombstone cannot be mistaken for an array and is overwritten normally
    // the next time a new hazard is saved.
    var remotePromise = Promise.resolve();
    if (_fbReady && _fbDb) {
      remotePromise = Promise.all([
        _fbDb.ref("fiso/" + LS_KEY_HAZARDS).set({
          __cleared: true,
          clearedAt: new Date().toISOString()
        }),
        publishSharedAutoPibSnapshot([], "Admin clear plotted NOTAMs")
      ]).catch(function (err) {
        console.error("FFApp failed to clear shared hazards:", err);
        throw err;
      });
    }

    return remotePromise.then(function () {
      // Keep suppression on briefly so any old in-flight snapshots are ignored.
      setTimeout(function () { window.__FFAPP_CLEARING_PLOTTED_NOTAMS = false; }, 1200);
      return { hazards: hazards.length, notams: notams.length, nextRef: refInput ? refInput.value : "1" };
    }, function (err) {
      window.__FFAPP_CLEARING_PLOTTED_NOTAMS = false;
      throw err;
    });
  }

  function runClearPlottedNotams() {
    if (userRole !== "admin") {
      window.alert("Admin access only");
      return;
    }
    if (!window.confirm("Clear every currently plotted NOTAM and reset the Activity Ref PIN counter to zero?\n\nThe next plotted activity will use Ref 1. The active PIB, ENR 5.1 library and Managed Danger Areas will not be deleted.")) return;

    var btn = document.getElementById("clearPlottedNotamsBtn");
    if (btn) btn.disabled = true;
    clearAllPlottedNotamsAndResetRefs().then(function (result) {
      setPibStatus("All plotted NOTAM pins, polygons and parsed NOTAM layers cleared. Activity Ref counter reset to 0; the next pin will be Ref 1. The active PIB remains loaded.", false);
      console.info("FFApp clear plotted NOTAMs verified result:", result);
    }).catch(function (err) {
      setPibStatus("Unable to clear the shared plotted NOTAMs. Please check the connection and try again.", true);
      console.error(err);
    }).finally(function () {
      if (btn) btn.disabled = false;
    });
  }

  window.FFAPP_CLEAR_PLOTTED_NOTAMS = runClearPlottedNotams;
  var clearPlottedNotamsBtn = document.getElementById("clearPlottedNotamsBtn");
  if (clearPlottedNotamsBtn) {
    clearPlottedNotamsBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      runClearPlottedNotams();
    });
  }

  /* ---- Release232: visible PIB loading / pressed-button feedback ---- */
  function ffSetPressedButton(btn, pressed, label) {
    if (!btn) return;
    if (pressed) {
      if (!btn.dataset.ffOriginalText) btn.dataset.ffOriginalText = btn.textContent || "";
      btn.disabled = true;
      btn.setAttribute("aria-busy", "true");
      btn.style.transform = "translateY(2px)";
      btn.style.boxShadow = "inset 0 2px 7px rgba(0,0,0,.55)";
      btn.style.filter = "brightness(.80)";
      btn.style.opacity = ".88";
      if (label) btn.textContent = label;
    } else {
      btn.disabled = false;
      btn.removeAttribute("aria-busy");
      btn.style.transform = "";
      btn.style.boxShadow = "";
      btn.style.filter = "";
      btn.style.opacity = "";
      if (btn.dataset.ffOriginalText) {
        btn.textContent = btn.dataset.ffOriginalText;
        delete btn.dataset.ffOriginalText;
      }
    }
  }

  function ffSetPressedLabel(label, pressed, text) {
    if (!label) return;
    if (pressed) {
      if (!label.dataset.ffOriginalText) label.dataset.ffOriginalText = label.textContent || "";
      label.style.transform = "translateY(2px)";
      label.style.boxShadow = "inset 0 2px 7px rgba(0,0,0,.55)";
      label.style.filter = "brightness(.80)";
      label.style.opacity = ".88";
      label.style.pointerEvents = "none";
      label.setAttribute("aria-busy", "true");
      if (text) label.textContent = text;
    } else {
      label.style.transform = "";
      label.style.boxShadow = "";
      label.style.filter = "";
      label.style.opacity = "";
      label.style.pointerEvents = "";
      label.removeAttribute("aria-busy");
      if (label.dataset.ffOriginalText) {
        label.textContent = label.dataset.ffOriginalText;
        delete label.dataset.ffOriginalText;
      }
    }
  }



  /* ---- DEV407: LIVE NATS AUTO PIB + operational health / change log --- */
  var LIVE_PIB_ENDPOINT = "/api/pib-cache";
