  function applyLayerVisibility() {
    // aircraftLayer is ALWAYS on the map — handle() controls which markers appear in it
    [
      ["hazards", hazardLayer],
      ["notams", notamLayer],
      ["airfields", airfieldLayer],
      ["vectorLines", vectorLineLayer],
      ["airports", airportLayer],
    ].forEach(function (pair) {
      var on = settings.layers[pair[0]];
      if (on) {
        if (!map.hasLayer(pair[1])) map.addLayer(pair[1]);
      } else {
        if (map.hasLayer(pair[1])) map.removeLayer(pair[1]);
      }
    });
    // The original hazard checkbox is the master for both displays.
    var todayCheckbox=document.getElementById("fisoTodayHazards");
    if(todayCheckbox)todayCheckbox.disabled=!settings.layers.hazards||userRole==="viewer";
    if(!settings.layers.hazards&&todayHazardsTimer)setTodayHazards(false);
    // Dense reference airfields are additionally zoom-dependent (DEV393).
    refreshLaasAirfieldLabels();
  }
