  /* ============================ WEATHER (RainViewer live rain radar) ============================ */
  var WEATHER_REFRESH_MS = 10 * 60 * 1000;

  function fetchWeatherFrames(cb) {
    fetch("https://api.rainviewer.com/public/weather-maps.json", {
      cache: "no-cache",
    })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.json();
      })
      .then(function (data) {
        weatherFrames = data;
        if (cb) cb(null);
      })
      .catch(function (err) {
        console.warn("RainViewer fetch failed:", err);
        if (cb) cb(err);
      });
  }

  function buildRadarLayer() {
    if (!weatherFrames) return null;
    var past = (weatherFrames.radar && weatherFrames.radar.past) || [];
    if (!past.length) return null;
    var frame = past[past.length - 1];
    var host = weatherFrames.host || "https://tilecache.rainviewer.com";
    var url = host + frame.path + "/256/{z}/{x}/{y}/2/1_1.png";
    return L.tileLayer(url, {
      pane: "weatherPane",
      opacity: settings.radarOpacity,
      maxNativeZoom: 7,
      maxZoom: 19,
      tileSize: 256,
      attribution:
        'Rain &copy; <a href="https://www.rainviewer.com/">RainViewer</a>',
    });
  }

  function buildSatelliteLayer() {
    if (!weatherFrames) return null;
    var ir =
      (weatherFrames.satellite && weatherFrames.satellite.infrared) || [];
    if (!ir.length) return null;
    var frame = ir[ir.length - 1];
    var host = weatherFrames.host || "https://tilecache.rainviewer.com";
    var url = host + frame.path + "/256/{z}/{x}/{y}/0/0_0.png";
    return L.tileLayer(url, {
      pane: "weatherPane",
      opacity: settings.satelliteOpacity,
      maxNativeZoom: 8,
      maxZoom: 19,
      tileSize: 256,
      attribution:
        'Satellite IR &copy; <a href="https://www.rainviewer.com/">RainViewer</a>',
    });
  }

  function refreshWeatherLayers() {
    fetchWeatherFrames(function (err) {
      if (radarTileLayer) {
        map.removeLayer(radarTileLayer);
        radarTileLayer = null;
      }
      if (satelliteTileLayer) {
        map.removeLayer(satelliteTileLayer);
        satelliteTileLayer = null;
      }
      if (settings.layers.radar && !err) {
        radarTileLayer = buildRadarLayer();
        if (radarTileLayer) radarTileLayer.addTo(map);
      }
      if (settings.layers.satellite && !err) {
        satelliteTileLayer = buildSatelliteLayer();
        if (satelliteTileLayer) satelliteTileLayer.addTo(map);
      }
    });
  }

  // DEV439: fetch optional weather metadata only for enabled weather layers.
  if (settings.layers.radar || settings.layers.satellite)
    refreshWeatherLayers();

  setInterval(function () {
    if (settings.layers.radar || settings.layers.satellite)
      refreshWeatherLayers();
  }, WEATHER_REFRESH_MS);

