  // DEV372 — floating R&B dialog wires.
  (function wireFloatingRangeBearing(){
    var dlg = document.getElementById("rbFloatingDialog");
    if (!dlg) return;
    var dragHead = dlg.querySelector(".rb-floating-header");
    if (dragHead) {
      var drag = null;
      dragHead.addEventListener("pointerdown", function(e){
        if (e.target && e.target.closest && e.target.closest("button")) return;
        var r = dlg.getBoundingClientRect();
        drag = {dx:e.clientX-r.left, dy:e.clientY-r.top};
        dlg.dataset.userMoved = "1";
        try { dragHead.setPointerCapture(e.pointerId); } catch(_e) {}
        e.preventDefault();
      });
      dragHead.addEventListener("pointermove", function(e){
        if (!drag) return;
        var w = dlg.offsetWidth, h = dlg.offsetHeight;
        var left = Math.max(4, Math.min(window.innerWidth - w - 4, e.clientX - drag.dx));
        var top = Math.max(4, Math.min(window.innerHeight - h - 4, e.clientY - drag.dy));
        dlg.style.left = Math.round(left) + "px";
        dlg.style.top = Math.round(top) + "px";
        dlg.style.transform = "none";
      });
      function stopDrag(e){
        if (!drag) return;
        drag = null;
        try { dragHead.releasePointerCapture(e.pointerId); } catch(_e) {}
      }
      dragHead.addEventListener("pointerup", stopDrag);
      dragHead.addEventListener("pointercancel", stopDrag);
    }
    var sEl = document.getElementById("rbfStart");
    var eEl = document.getElementById("rbfEnd");
    function focus(which){ rbFocusedEnd = which; rbHookArmed = null; rbRefresh(); }
    if (sEl) {
      sEl.addEventListener("focus", function(){ focus("start"); rbUpdateSuggestions("start", sEl.value); });
      sEl.addEventListener("input", function(){ rbUpdateSuggestions("start", sEl.value); });
      sEl.addEventListener("keydown", function(e){ if(e.key === "Enter") { rbFinishSuggestions("start"); rbApplyTextInput("start", sEl.value); } if(e.key === "Escape") rbFinishSuggestions("start"); });
    }
    if (eEl) {
      eEl.addEventListener("focus", function(){ focus("end"); rbUpdateSuggestions("end", eEl.value); });
      eEl.addEventListener("input", function(){ rbUpdateSuggestions("end", eEl.value); });
      eEl.addEventListener("keydown", function(e){ if(e.key === "Enter") { rbFinishSuggestions("end"); rbApplyTextInput("end", eEl.value); } if(e.key === "Escape") rbFinishSuggestions("end"); });
    }
    ["start","end"].forEach(function(which){
      var box=rbSuggestionBox(which);
      if(!box) return;
      box.addEventListener("mousedown",function(e){ e.preventDefault(); });
      box.addEventListener("click",function(e){
        var btn=e.target.closest("button[data-rb-suggest]"); if(!btn) return;
        var item=(box.__items||[])[Number(btn.getAttribute("data-rb-suggest"))]; if(!item) return;
        if(item.kind==="waypoint") { var wp=findUkWaypoint(item.ident); if(wp) setRbEndpointToWaypoint(which,wp,false); }
        else rbSetEndpointToPlace(which,item);
        var input=document.getElementById(which==="start"?"rbfStart":"rbfEnd"); if(input) input.value=rbFormatEndLabel(which);
        rbFinishSuggestions(which);
      });
    });
    document.getElementById("rbfUpdate").addEventListener("click", function(){
      if (rbFocusedEnd === "end") rbApplyTextInput("end", eEl.value);
      else rbApplyTextInput("start", sEl.value);
    });
    document.getElementById("rbfStartHook").addEventListener("click", function(){
      rbFocusedEnd = "start"; rbToggleHookButton("start");
      rbSetFloatingStatus(rbStartHex ? "Start unhooked." : "Click an aircraft to hook the Start end.");
    });
    document.getElementById("rbfEndHook").addEventListener("click", function(){
      rbFocusedEnd = "end"; rbToggleHookButton("end");
      rbSetFloatingStatus(rbEndHex ? "End unhooked." : "Click an aircraft to hook the End end.");
    });
    document.getElementById("rbfCentre").addEventListener("click", function(){
      rbCentreLineOnMap(); rbSetFloatingStatus("R&B line centred on the current map view.");
    });
    document.getElementById("rbfClear").addEventListener("click", function(){
      rbFocusedEnd = null; rbHookArmed = null;
      var t = document.getElementById("rbToggle"); if (t) t.checked = false;
      rbSetActive(false); dlg.hidden = true;
    });
    document.getElementById("rbFloatingClose").addEventListener("click", function(){
      rbFocusedEnd = null; rbHookArmed = null; dlg.hidden = true; rbRefresh();
    });
  })();

